{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; create or replace table snitch_db.maplemonk.sru_repeats_mp_sor as WITH meta_map AS ( SELECT UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'LONG TAIL\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'PLUS\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'LUXE\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'SNITCH\' THEN a.l1_category END), MIN(a.l1_category) ) AS l1_category, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.category END), MIN(a.category) ) AS category, MAX(COGS) AS COGS FROM snitch_db.maplemonk.meta_mapping_cogs_sku a GROUP BY 1 ), main AS ( SELECT _airbyte_data:\"Channel Ledger\"::STRING AS channel_ledger, _airbyte_data:\"Entity\"::STRING AS entity, _airbyte_data:\"Facility\"::STRING AS facility, NULLIF(_airbyte_data:\"GRN Price Without Tax\"::STRING, \'\')::FLOAT AS grn_price_without_tax, NULLIF(_airbyte_data:\"MRP\"::STRING, \'\')::FLOAT AS mrp, _airbyte_data:\"Original_Created_Date\"::TIMESTAMP AS original_created_date, TRY_TO_DATE(_airbyte_data:\"Original_Invoice_Date\"::VARCHAR, \'DD-MM-YYYY\') AS original_invoice_date, _airbyte_data:\"Product SKU Code\"::STRING AS product_sku_code, NULLIF(_airbyte_data:\"Quantity\"::STRING, \'\')::INTEGER AS quantity, _airbyte_data:\"Sale Order Number\"::STRING AS sale_order_number, NULLIF(_airbyte_data:\"Sales\"::STRING, \'\')::FLOAT AS sales, NULLIF(_airbyte_data:\"Total\"::STRING, \'\')::FLOAT AS total FROM snitch_db.maplemonk._AIRBYTE_RAW_UC_AARYAN_GET_TALLY_GST_REPORT QUALIFY ROW_NUMBER() OVER ( PARTITION BY _airbyte_data:\"Sale Order Number\"::STRING, _airbyte_data:\"Product SKU Code\"::STRING, _airbyte_data:\"Warehouse Name\"::STRING, _airbyte_data:\"Original_Created_Date\"::TIMESTAMP ORDER BY _airbyte_data:\"Ingested At\"::TIMESTAMP DESC ) = 1 UNION ALL SELECT channel_ledger, entity, facility, grn_price_without_tax, mrp, original_created_date, TO_DATE(Original_Invoice_Date, \'DD-MM-YYYY\') AS original_invoice_date, product_sku_code, quantity, sale_order_number, sales, total FROM snitch_db.MAPLEMONK.MIS_JAN206_MAY20260502 UNION ALL SELECT GET(VARIANT_COL, \'Channel Ledger\')::STRING, GET(VARIANT_COL, \'Entity\')::STRING, GET(VARIANT_COL, \'Facility\')::STRING, GET(VARIANT_COL, \'GRN Price Without Tax\')::FLOAT, GET(VARIANT_COL, \'MRP\')::FLOAT, GET(VARIANT_COL, \'Original_Created_Date\')::TIMESTAMP, TO_DATE(GET(VARIANT_COL, \'Original_Invoice_Date\')::VARCHAR, \'DD-MM-YYYY\'), GET(VARIANT_COL, \'Product SKU Code\')::STRING, GET(VARIANT_COL, \'Quantity\')::INT, GET(VARIANT_COL, \'Sale Order Number\')::STRING, GET(VARIANT_COL, \'Sales\')::FLOAT, GET(VARIANT_COL, \'Total\')::FLOAT FROM snitch_db.MAPLEMONK.mis_feb_20260504 UNION ALL SELECT channel_ledger, entity, facility, grn_price_without_tax, mrp, original_created_date, TO_DATE(Original_Invoice_Date, \'DD-MM-YYYY\') AS original_invoice_date, product_sku_code, quantity, sale_order_number, sales, total FROM snitch_db.MAPLEMONK.MIS_20260428 ), cost_price_map AS ( SELECT sku_group, cost_price, category FROM snitch_db.maplemonk.base_product QUALIFY ROW_NUMBER() OVER (PARTITION BY sku_group ORDER BY cost_price DESC) = 1 ), fin_gross AS ( SELECT a.original_invoice_date AS date, a.sale_order_number AS order_name, TRIM(UPPER(REVERSE(SUBSTRING(REVERSE(a.product_sku_code), CHARINDEX(\'-\', REVERSE(a.product_sku_code)) + 1, LEN(a.product_sku_code))))) AS sku_group, CASE WHEN a.channel_ledger IN ( \'AMAZON_FLEX_WH2\',\'AMAZON_SAPL\',\'AMAZON_SAPL_TAURU\',\'COCOBLU_WH2\',\'COCOBLU_NORTH\',\'COCOBLU_WH1\') THEN \'Amazon\' WHEN a.channel_ledger IN (\'FLIPKART_SAPLWH2\', \'SAPL_EMIZA_FLIPKART\', \'SAPL_FLIPKART\', \'FLIPKART_TAURU\') THEN \'Flipkart\' WHEN a.channel_ledger IN (\'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\') THEN \'Myntra\' END AS channel, SUM(a.quantity) AS quantity, SUM( CASE WHEN UPPER(TRIM(a.channel_ledger)) IN (\'AMAZON_FLEX_WH2\',\'AMAZON_SAPL\',\'AMAZON_SAPL_TAURU\', \'COCOBLU_WH2\',\'COCOBLU_NORTH\',\'COCOBLU_WH1\') THEN a.total WHEN a.channel_ledger IN (\'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\') AND a.original_invoice_date >= \'2026-03-26\' THEN a.total + a.quantity * c.avg_cat_charges WHEN a.channel_ledger IN (\'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\') THEN a.total WHEN a.channel_ledger IN (\'FLIPKART_SAPLWH2\', \'SAPL_EMIZA_FLIPKART\', \'SAPL_FLIPKART\', \'FLIPKART_TAURU\') THEN (a.total / 0.82)::INT ELSE a.sales END )::INT AS sales, SUM( COALESCE(TRY_TO_NUMBER(NULLIF(REGEXP_REPLACE(a.grn_price_without_tax, \'[^0-9.-]\', \'\'), \'\')), 0) * COALESCE(TRY_TO_NUMBER(NULLIF(REGEXP_REPLACE(a.quantity, \'[^0-9.-]\', \'\'), \'\')), 0) ) AS cp FROM main a LEFT JOIN cost_price_map b ON TRIM(UPPER(REVERSE(SUBSTRING(REVERSE(a.product_sku_code), CHARINDEX(\'-\', REVERSE(a.product_sku_code)) + 1, LEN(a.product_sku_code))))) = b.sku_group LEFT JOIN snitch_db.maplemonk.AVG_GT_CHARGES c ON b.category = c.category WHERE a.channel_ledger IN ( \'AMAZON_FLEX_WH2\', \'AMAZON_SAPL\', \'FLIPKART_SAPLWH2\', \'SAPL_EMIZA_FLIPKART\', \'SAPL_FLIPKART\', \'FLIPKART_TAURU\', \'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\',\'AMAZON_SAPL_TAURU\',\'COCOBLU_WH2\',\'COCOBLU_NORTH\',\'COCOBLU_WH1\') GROUP BY 1, 2, 3, 4 ) , fin_return AS ( SELECT \"Display Order Number\" AS order_name, TRIM(UPPER(REVERSE(SUBSTRING(REVERSE(\"Product SKU Code\"), CHARINDEX(\'-\', REVERSE(\"Product SKU Code\")) + 1, LEN(\"Product SKU Code\"))))) AS sku_group, SUM(QTY) AS return_qty FROM snitch_db.maplemonk.uc_get_tally_return_gst_report WHERE \"Channel Ledger\" IN ( \'AMAZON_FLEX_WH2\', \'AMAZON_SAPL\', \'FLIPKART_SAPLWH2\', \'SAPL_EMIZA_FLIPKART\', \'SAPL_FLIPKART\', \'FLIPKART_TAURU\', \'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\' ) GROUP BY 1, 2 ), fin_pre AS ( SELECT a.date, a.sku_group, a.channel, a.quantity, a.quantity - LEAST(a.quantity, IFNULL(b.return_qty, 0)) AS net_quantity, a.sales, a.sales * (a.quantity - LEAST(a.quantity, IFNULL(b.return_qty, 0))) / NULLIF(a.quantity, 0) AS net_sales, a.cp, a.cp * (a.quantity - LEAST(a.quantity, IFNULL(b.return_qty, 0))) / NULLIF(a.quantity, 0) AS net_cp FROM fin_gross a LEFT JOIN fin_return b ON a.order_name = b.order_name AND a.sku_group = b.sku_group ), fin_daily AS ( SELECT date, sku_group, channel, SUM(quantity) AS quantity, SUM(net_quantity) AS net_quantity, SUM(sales) AS sales, SUM(net_sales) AS net_sales, SUM(cp) AS cost_price, SUM(net_cp) AS net_cost_price FROM fin_pre GROUP BY 1, 2, 3 ), mp_h AS ( SELECT d, sku_group, channel, is_sor, qty, revenue FROM ( SELECT date::DATE AS d, UPPER(TRIM(sku_group)) AS sku_group, CASE WHEN LOWER(channel) LIKE \'%amazon%\' THEN \'Amazon\' WHEN LOWER(channel) LIKE \'%myntra%\' OR REGEXP_LIKE(LOWER(channel), \'.*m[- ]?now.*\') THEN \'Myntra\' WHEN LOWER(channel) LIKE \'%flipkart%\' THEN \'Flipkart\' END AS channel, IFF(LOWER(channel) LIKE \'%sor%\', 1, 0) AS is_sor, gross_quantity AS qty, gross_sales AS revenue FROM snitch_db.maplemonk.horizontal_sales_categories WHERE sku_group NOT LIKE \'CBB%\' AND channel NOT LIKE \'%WH%\' ) WHERE channel IS NOT NULL ), mp_sor_s3 AS ( SELECT TRY_TO_DATE(NULLIF(TRIM(a.order_created_date::VARCHAR), \'\'), \'YYYYMMDD\') AS d, UPPER(TRIM(a.style)) AS sku_group, \'Myntra\' AS channel, 1 AS is_sor, TRY_TO_NUMBER(REPLACE(TRIM(a.sales::STRING), \',\', \'\')) AS qty, TRY_TO_NUMBER(REPLACE(TRIM(a.revenue::STRING), \',\', \'\')) AS revenue FROM snitch_db.maplemonk.S3_MYNTRA_B2B_GP a UNION ALL SELECT TRY_TO_DATE(NULLIF(TRIM(a.order_date_key::VARCHAR), \'\'), \'YYYYMMDD\') AS d, UPPER(TRIM(a.STYLE)) AS sku_group, \'Flipkart\' AS channel, 1 AS is_sor, TRY_TO_NUMBER(REPLACE(TRIM(a.units::STRING), \',\', \'\')) AS qty, TRY_TO_NUMBER(REPLACE(TRIM(a.SP_Qty::STRING), \',\', \'\')) AS revenue FROM snitch_db.maplemonk.S3_Flipkart_B2B_GP a ), mp_sales AS ( SELECT d, sku_group, channel, is_sor, SUM(qty) AS qty, SUM(revenue) AS revenue FROM ( SELECT d, channel, is_sor, qty, revenue, IFF( c LIKE \'MP%\' OR c LIKE \'4C-%\' OR c like \'FK-%\', SPLIT_PART(c, \'-\', 1) || \'-\' || SPLIT_PART(c, \'-\', 2) || IFF(SPLIT_PART(c, \'-\', 3) = \'\', \'\', \'-\' || SPLIT_PART(c, \'-\', 3)), SPLIT_PART(c, \'-\', 1) || IFF(SPLIT_PART(c, \'-\', 2) = \'\', \'\', \'-\' || SPLIT_PART(c, \'-\', 2)) ) AS sku_group FROM ( SELECT d, channel, is_sor, qty, revenue, REPLACE(UPPER(TRIM(sku_group)), \' \', \'\') AS c FROM ( SELECT * FROM mp_h UNION ALL SELECT * FROM mp_sor_s3 ) ) ) WHERE d IS NOT NULL GROUP BY 1, 2, 3, 4 ), inv_raw AS ( SELECT DATE::DATE AS inv_date, UPPER(TRIM(REGEXP_REPLACE(\"Item SkuCode\", \'-[^-]+$\', \'\'))) AS sku_group, UPPER(TRIM(REGEXP_REPLACE(\"Item SkuCode\", \'^.*-\', \'\'))) AS raw_size, inventory AS qty FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE facility IN (\'SAPL-WH2\', \'SAPL-WH1\', \'SAPL-NORTH-TAURU\') ), inv_norm AS ( SELECT inv_date, sku_group, size, SUM(qty) AS qty FROM ( SELECT inv_date, sku_group, qty, CASE WHEN raw_size IS NULL OR TRIM(raw_size) = \'\' THEN \'L\' WHEN raw_size = \'01M\' THEN \'M\' WHEN raw_size = \'01XL\' THEN \'XL\' WHEN raw_size = \'06XL\' THEN \'6XL\' WHEN raw_size IN (\'XS\',\'S\',\'M\',\'L\',\'XL\') THEN raw_size WHEN raw_size IN (\'XXL\',\'2XL\',\'XXU\') THEN \'2XL\' WHEN raw_size IN (\'XXXL\',\'3XL\') THEN \'3XL\' WHEN raw_size IN (\'4XL\',\'5XL\',\'6XL\',\'7XL\',\'8XL\') THEN raw_size WHEN raw_size = \'28\' THEN \'XS\' WHEN raw_size = \'30\' THEN \'S\' WHEN raw_size = \'32\' THEN \'M\' WHEN raw_size = \'34\' THEN \'L\' WHEN raw_size = \'36\' THEN \'XL\' WHEN raw_size IN (\'38\',\'39\') THEN \'2XL\' WHEN raw_size = \'40\' THEN \'3XL\' WHEN raw_size IN (\'41\',\'42\') THEN \'4XL\' WHEN raw_size IN (\'43\',\'44\') THEN \'5XL\' WHEN raw_size IN (\'45\',\'46\') THEN \'6XL\' WHEN raw_size = \'48\' THEN \'7XL\' WHEN raw_size = \'50\' THEN \'8XL\' WHEN raw_size = \'1\' THEN \'XS\' WHEN raw_size = \'2\' THEN \'S\' WHEN raw_size = \'3\' THEN \'M\' WHEN raw_size = \'4\' THEN \'L\' WHEN raw_size = \'5\' THEN \'XL\' WHEN raw_size = \'6\' THEN \'2XL\' ELSE raw_size END AS size FROM inv_raw ) GROUP BY 1, 2, 3 ), sku_grp_map AS ( SELECT g.sku_group, LOWER(m.l1_category) AS l1_category, LOWER(m.category) AS category, M.COGS AS COGS, CASE WHEN UPPER(m.l1_category) = \'PLUS\' THEN \'PLUS\' WHEN UPPER(m.l1_category) IN (\'SNITCH\', \'LUXE\') THEN \'REG\' END AS grp FROM ( SELECT sku_group FROM inv_norm UNION SELECT sku_group FROM mp_sales ) g LEFT JOIN meta_map m ON m.sku_group_clean = UPPER( IFF( UPPER(REPLACE(g.sku_group, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(g.sku_group, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(g.sku_group, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(g.sku_group, \' \', \'\'), \'-.*$\', \'\') ) ) ), nc_days AS ( SELECT i.inv_date, i.sku_group FROM inv_norm i JOIN sku_grp_map g ON g.sku_group = i.sku_group WHERE g.grp IS NOT NULL GROUP BY i.inv_date, i.sku_group, g.grp HAVING COUNT(DISTINCT IFF( i.qty >= 5 AND ( (g.grp = \'REG\' AND i.size IN (\'S\',\'M\',\'L\',\'XL\')) OR (g.grp = \'PLUS\' AND i.size IN (\'3XL\',\'4XL\',\'5XL\',\'6XL\')) ), i.size, NULL)) = 4 ), first_sale AS ( SELECT sku_group, channel, MIN(d) AS first_sale_date FROM mp_sales GROUP BY 1, 2 ), initial_sale AS ( SELECT UPPER(TRIM(sku_group)) AS sku_group, MIN(date)::DATE AS initial_date FROM snitch_db.maplemonk.table_for_initial_date_of_sale GROUP BY 1 ), start_dt AS ( SELECT f.sku_group, f.channel, GREATEST(f.first_sale_date, COALESCE(i.initial_date, f.first_sale_date)) AS start_date FROM first_sale f LEFT JOIN initial_sale i ON i.sku_group = f.sku_group ), nonsor_pairs AS ( SELECT DISTINCT sku_group, channel FROM mp_sales WHERE is_sor = 0 ), nc_window AS ( SELECT n.sku_group, p.channel, n.inv_date FROM nc_days n JOIN nonsor_pairs p ON p.sku_group = n.sku_group JOIN start_dt s ON s.sku_group = n.sku_group AND s.channel = p.channel WHERE n.inv_date >= s.start_date AND n.inv_date <= CURRENT_DATE ), nc_inventory AS ( SELECT w.sku_group, w.channel, ROUND(AVG(i.daily_inventory), 2) AS avg_nc_inventory FROM nc_window w JOIN ( SELECT inv_date, sku_group, SUM(qty) AS daily_inventory FROM inv_norm GROUP BY 1, 2 ) i ON w.sku_group = i.sku_group AND w.inv_date = i.inv_date GROUP BY 1, 2 ), nonsor_agg AS ( SELECT w.sku_group, w.channel, COUNT(*) AS live_days_nonsor, SUM(COALESCE(s.qty, 0)) AS qty_nonsor, SUM(COALESCE(s.revenue, 0)) AS revenue_nonsor FROM nc_window w LEFT JOIN mp_sales s ON s.sku_group = w.sku_group AND s.channel = w.channel AND s.d = w.inv_date AND s.is_sor = 0 GROUP BY 1, 2 ), sor_agg AS ( SELECT s.sku_group, s.channel, COUNT(DISTINCT s.d) AS live_days_sor, SUM(s.qty) AS qty_sor, SUM(s.revenue) AS revenue_sor FROM mp_sales s JOIN start_dt t ON t.sku_group = s.sku_group AND t.channel = s.channel WHERE s.is_sor = 1 AND s.qty > 0 AND s.d >= t.start_date AND s.d <= CURRENT_DATE GROUP BY 1, 2 ), fin_agg AS ( SELECT f.sku_group, f.channel, SUM(f.quantity) AS fin_gross_qty, SUM(f.net_quantity) AS fin_net_qty, SUM(f.sales) AS fin_gross_sales, SUM(f.net_sales) AS fin_net_sales, SUM(f.cost_price) AS cogs_sold, SUM(f.net_cost_price) AS net_cogs FROM fin_daily f JOIN start_dt s ON s.sku_group = f.sku_group AND s.channel = f.channel WHERE f.date >= s.start_date AND f.date <= CURRENT_DATE GROUP BY 1, 2 ), keys AS ( SELECT sku_group, channel FROM nonsor_agg UNION SELECT sku_group, channel FROM sor_agg ), base_output AS ( SELECT k.sku_group, k.channel, g.l1_category, g.category, G.COGS, s.start_date, COALESCE(n.live_days_nonsor, 0) AS live_days_nonsor, COALESCE(r.live_days_sor, 0) AS live_days_sor, COALESCE(n.qty_nonsor, 0) AS qty_nonsor, COALESCE(r.qty_sor, 0) AS qty_sor, COALESCE(n.qty_nonsor, 0) + COALESCE(r.qty_sor, 0) AS qty_sold, COALESCE(n.revenue_nonsor, 0) + COALESCE(r.revenue_sor, 0) AS revenue, ROUND(COALESCE(n.qty_nonsor / NULLIF(n.live_days_nonsor, 0), 0), 3) AS ros_nonsor, COALESCE(ni.avg_nc_inventory, 0) AS AVG_NC_INVENTORY, ROUND( COALESCE(n.qty_nonsor, 0) * 100.0 / NULLIF( COALESCE(n.qty_nonsor, 0) + COALESCE(ni.avg_nc_inventory, 0), 0 ), 2 ) AS STR_NONSOR, ROUND(COALESCE(r.qty_sor / NULLIF(r.live_days_sor, 0), 0), 3) AS ros_sor, ROUND( COALESCE(n.qty_nonsor / NULLIF(n.live_days_nonsor, 0), 0) + COALESCE(r.qty_sor / NULLIF(r.live_days_sor, 0), 0), 3 ) AS ros, COALESCE(f.fin_gross_qty, 0) AS fin_gross_qty, COALESCE(f.fin_gross_qty, 0) - COALESCE(f.fin_net_qty, 0) AS return_qty, ROUND((f.fin_gross_qty - f.fin_net_qty) / NULLIF(f.fin_gross_qty, 0) * 100, 2) AS returns_pct, f.fin_gross_sales, f.fin_net_sales, f.cogs_sold, f.net_cogs, f.fin_net_sales - f.net_cogs AS margin, ROUND( CASE WHEN f.fin_net_sales > 0 THEN (f.fin_net_sales - f.net_cogs) / NULLIF(f.fin_net_sales, 0) * 100 WHEN f.fin_gross_sales > 0 THEN (f.fin_gross_sales - f.cogs_sold) / NULLIF(f.fin_gross_sales, 0) * 100 ELSE NULL END, 2 ) AS GP_PCT FROM keys k JOIN start_dt s ON s.sku_group = k.sku_group AND s.channel = k.channel JOIN sku_grp_map g ON g.sku_group = k.sku_group LEFT JOIN nonsor_agg n ON n.sku_group = k.sku_group AND n.channel = k.channel LEFT JOIN sor_agg r ON r.sku_group = k.sku_group AND r.channel = k.channel LEFT JOIN fin_agg f ON f.sku_group = k.sku_group AND f.channel = k.channel LEFT JOIN nc_inventory ni ON ni.sku_group = k.sku_group AND ni.channel = k.channel ), benchmarks AS ( SELECT b.*, AVG(b.ros) OVER ( PARTITION BY b.category, b.l1_category ) AS avg_ros, ROUND( b.ros / NULLIF( AVG(b.ros) OVER ( PARTITION BY b.category, b.l1_category ), 0 ), 4 ) AS ROS_INDEX, AVG(b.returns_pct) OVER ( PARTITION BY b.l1_category, b.category ) AS avg_returns_pct FROM base_output b ) SELECT b.*, CASE WHEN ( (UPPER(TRIM(b.l1_category)) = \'SNITCH\' AND b.ros > 10) OR (UPPER(TRIM(b.l1_category)) IN (\'PLUS\', \'LUXE\') AND b.ros > 5) ) AND b.gp_pct > 55 AND b.returns_pct < b.avg_returns_pct THEN \'repeat\' ELSE \'no repeat\' END AS R1, CASE WHEN b.ros > b.avg_ros AND b.gp_pct > 52 AND b.returns_pct < b.avg_returns_pct THEN \'repeat\' ELSE \'no repeat\' END AS R2 FROM benchmarks b ORDER BY b.sku_group, b.channel ; create or replace table snitch_db.maplemonk.sru_repeats_shopify as WITH meta_map AS ( SELECT UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE( REPLACE(SKU_GROUP, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\' ), REGEXP_REPLACE( REPLACE(SKU_GROUP, \' \', \'\'), \'-.*$\', \'\' ) ) ) AS sku_group_clean, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'LONG TAIL\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'PLUS\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'LUXE\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'SNITCH\' THEN a.l1_category END), MIN(a.l1_category) ) AS l1_category, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.category END), MIN(CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.category END), MIN(a.category) ) AS category FROM snitch_db.maplemonk.meta_mapping_cogs_sku_2 a GROUP BY 1 ), cogs_map AS ( SELECT UPPER(TRIM(sku_group)) AS sku_group, MAX(cogs) AS cogs FROM snitch_db.maplemonk.meta_mapping_cogs_sku GROUP BY 1 ), raw_union AS ( SELECT \'SALES\' AS src, date::DATE AS d, UPPER(TRIM(sku_group)) AS sku_group, UPPER(TRIM(TO_VARCHAR(size))) AS raw_size, gross_quantity AS qty, gross_sales AS revenue FROM snitch_db.maplemonk.horizontal_sales_categories WHERE type = \'Shopify\' AND sku_group NOT LIKE \'CBB%\' UNION ALL SELECT \'INV\' AS src, DATE::DATE AS d, UPPER(TRIM( CASE WHEN POSITION(\'-\' IN \"Item SkuCode\") > 0 THEN LEFT( \"Item SkuCode\", LENGTH(\"Item SkuCode\") - POSITION(\'-\', REVERSE(\"Item SkuCode\")) ) ELSE \"Item SkuCode\" END )) AS sku_group, UPPER(TRIM( COALESCE( REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'), \"Item SkuCode\" ) )) AS raw_size, inventory AS qty, NULL AS revenue FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE facility IN ( \'SAPL-WH2\', \'SAPL-WH1\', \'SAPL-NORTH-TAURU\' ) UNION ALL SELECT \'RET\' AS src, order_date::DATE AS d, UPPER(TRIM( CASE WHEN POSITION(\'-\' IN sku) > 0 THEN LEFT( sku, LENGTH(sku) - POSITION(\'-\', REVERSE(sku)) ) ELSE sku END )) AS sku_group, UPPER(TRIM( COALESCE( REGEXP_SUBSTR(sku, \'[^-]+$\'), sku ) )) AS raw_size, return_qty AS qty, NULL AS revenue FROM snitch_db.maplemonk.return_fact_items WHERE reason NOT IN (\'not_returned\') ), sized AS ( SELECT src, d, sku_group, qty, revenue, CASE WHEN raw_size = \'01M\' THEN \'M\' WHEN raw_size = \'01XL\' THEN \'XL\' WHEN raw_size = \'06XL\' THEN \'6XL\' WHEN raw_size IN (\'XS\',\'S\',\'M\',\'L\',\'XL\') THEN raw_size WHEN raw_size IN (\'XXL\',\'2XL\',\'XXU\') THEN \'2XL\' WHEN raw_size IN (\'XXXL\',\'3XL\') THEN \'3XL\' WHEN raw_size IN (\'4XL\',\'5XL\',\'6XL\',\'7XL\',\'8XL\') THEN raw_size WHEN raw_size = \'28\' THEN \'XS\' WHEN raw_size = \'30\' THEN \'S\' WHEN raw_size = \'32\' THEN \'M\' WHEN raw_size = \'34\' THEN \'L\' WHEN raw_size = \'36\' THEN \'XL\' WHEN raw_size IN (\'38\',\'39\') THEN \'2XL\' WHEN raw_size = \'40\' THEN \'3XL\' WHEN raw_size IN (\'41\',\'42\') THEN \'4XL\' WHEN raw_size IN (\'43\',\'44\') THEN \'5XL\' WHEN raw_size IN (\'45\',\'46\') THEN \'6XL\' WHEN raw_size = \'48\' THEN \'7XL\' WHEN raw_size = \'50\' THEN \'8XL\' WHEN raw_size = \'1\' THEN \'XS\' WHEN raw_size = \'2\' THEN \'S\' WHEN raw_size = \'3\' THEN \'M\' WHEN raw_size = \'4\' THEN \'L\' WHEN raw_size = \'5\' THEN \'XL\' WHEN raw_size = \'6\' THEN \'2XL\' ELSE raw_size END AS size FROM raw_union ), shopify_sales AS ( SELECT d AS sale_date, sku_group, size, SUM(qty) AS qty, SUM(revenue) AS revenue FROM sized WHERE src = \'SALES\' GROUP BY 1,2,3 ), shopify_returns AS ( SELECT d AS order_date, sku_group, size, SUM(qty) AS qty FROM sized WHERE src = \'RET\' GROUP BY 1,2,3 ), inv_norm AS ( SELECT d AS inv_date, sku_group, size, SUM(qty) AS qty FROM sized WHERE src = \'INV\' GROUP BY 1,2,3 ), sku_grp_map AS ( SELECT g.sku_group, LOWER(m.l1_category) AS l1_category, LOWER(m.category) AS category, CASE WHEN UPPER(m.l1_category) = \'PLUS\' THEN \'PLUS\' WHEN UPPER(m.l1_category) IN (\'SNITCH\',\'LUXE\') THEN \'REG\' END AS grp FROM ( SELECT DISTINCT sku_group FROM sized ) g LEFT JOIN meta_map m ON m.sku_group_clean = UPPER( IFF( UPPER(REPLACE(g.sku_group, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(g.sku_group, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE( REPLACE(g.sku_group, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\' ), REGEXP_REPLACE( REPLACE(g.sku_group, \' \', \'\'), \'-.*$\', \'\' ) ) ) ), nc_days AS ( SELECT i.inv_date, i.sku_group FROM inv_norm i JOIN sku_grp_map g ON g.sku_group = i.sku_group WHERE g.grp IS NOT NULL GROUP BY i.inv_date, i.sku_group, g.grp HAVING COUNT( DISTINCT IFF( i.qty >= 5 AND ( ( g.grp = \'REG\' AND i.size IN (\'S\',\'M\',\'L\',\'XL\') ) OR ( g.grp = \'PLUS\' AND i.size IN (\'3XL\',\'4XL\',\'5XL\',\'6XL\') ) ), i.size, NULL ) ) = 4 ), first_sale AS ( SELECT sku_group, MIN(sale_date) AS first_sale_date FROM shopify_sales GROUP BY 1 ), initial_sale AS ( SELECT UPPER(TRIM(sku_group)) AS sku_group, MIN(date)::DATE AS initial_date FROM snitch_db.maplemonk.table_for_initial_date_of_sale GROUP BY 1 ), start_dt AS ( SELECT f.sku_group, GREATEST( f.first_sale_date, COALESCE( i.initial_date, f.first_sale_date ) ) AS start_date FROM first_sale f LEFT JOIN initial_sale i ON i.sku_group = f.sku_group ), nc_window AS ( SELECT n.sku_group, n.inv_date FROM nc_days n JOIN start_dt s ON s.sku_group = n.sku_group WHERE n.inv_date >= s.start_date AND n.inv_date < CURRENT_DATE ), nc_count AS ( SELECT sku_group, COUNT(*) AS nc_days FROM nc_window GROUP BY 1 ), size_sales AS ( SELECT w.sku_group, s.size, SUM(s.qty) AS sales_qty_nc, SUM(s.revenue) AS revenue_nc FROM nc_window w JOIN shopify_sales s ON s.sku_group = w.sku_group AND s.sale_date = w.inv_date GROUP BY 1,2 ), size_returns AS ( SELECT w.sku_group, r.size, SUM(r.qty) AS return_qty_nc FROM nc_window w JOIN shopify_returns r ON r.sku_group = w.sku_group AND r.order_date = w.inv_date GROUP BY 1,2 ), size_spine AS ( SELECT sku_group, size FROM shopify_sales UNION SELECT sku_group, size FROM inv_norm ), nc_daily_inventory AS ( SELECT w.sku_group, w.inv_date, SUM(COALESCE(i.qty, 0)) AS daily_inventory FROM nc_window w LEFT JOIN inv_norm i ON i.sku_group = w.sku_group AND i.inv_date = w.inv_date GROUP BY 1,2 ), avg_nc_inventory AS ( SELECT sku_group, AVG(daily_inventory) AS avg_inventory_nc_days FROM nc_daily_inventory GROUP BY 1 ), size_level_output AS ( SELECT c.sku_group, sp.size, c.nc_days, COALESCE(ss.sales_qty_nc, 0) AS sales_qty_nc, COALESCE(ss.revenue_nc, 0) AS revenue_nc, COALESCE(sr.return_qty_nc, 0) AS return_qty_nc, COALESCE(ss.sales_qty_nc, 0) / NULLIF(c.nc_days, 0) AS ros FROM nc_count c JOIN size_spine sp ON sp.sku_group = c.sku_group LEFT JOIN size_sales ss ON ss.sku_group = sp.sku_group AND ss.size = sp.size LEFT JOIN size_returns sr ON sr.sku_group = sp.sku_group AND sr.size = sp.size WHERE LOWER(sp.size) NOT LIKE \'dummy%\' ), sku_level_output AS ( SELECT sku_group, MAX(nc_days) AS nc_days, SUM(sales_qty_nc) AS total_sales_nc_days, SUM(revenue_nc) AS total_revenue_nc, SUM(return_qty_nc) AS total_returns_nc, SUM(CASE WHEN size = \'XS\' THEN ros ELSE 0 END) AS xs_ros, SUM(CASE WHEN size = \'S\' THEN ros ELSE 0 END) AS s_ros, SUM(CASE WHEN size = \'M\' THEN ros ELSE 0 END) AS m_ros, SUM(CASE WHEN size = \'L\' THEN ros ELSE 0 END) AS l_ros, SUM(CASE WHEN size = \'XL\' THEN ros ELSE 0 END) AS xl_ros, SUM(CASE WHEN size = \'2XL\' THEN ros ELSE 0 END) AS xxl_ros, SUM(CASE WHEN size = \'3XL\' THEN ros ELSE 0 END) AS xl3_ros, SUM(CASE WHEN size = \'4XL\' THEN ros ELSE 0 END) AS xl4_ros, SUM(CASE WHEN size = \'5XL\' THEN ros ELSE 0 END) AS xl5_ros, SUM(CASE WHEN size = \'6XL\' THEN ros ELSE 0 END) AS xl6_ros, SUM(CASE WHEN size = \'7XL\' THEN ros ELSE 0 END) AS xl7_ros, SUM(CASE WHEN size = \'8XL\' THEN ros ELSE 0 END) AS xl8_ros, SUM(ros) AS sku_ros FROM size_level_output GROUP BY 1 ), category_ros_index AS ( SELECT p.sku_group, g.category, g.l1_category, p.sku_ros, AVG(p.sku_ros) OVER ( PARTITION BY g.category, g.l1_category ) AS avg_category_l1_ros, ROUND( p.sku_ros / NULLIF( AVG(p.sku_ros) OVER ( PARTITION BY g.category, g.l1_category ), 0 ), 2 ) AS sku_ros_index FROM sku_level_output p JOIN sku_grp_map g ON g.sku_group = p.sku_group ), lifetime_sales AS ( SELECT sku_group, SUM(qty) AS lifetime_sold_qty, SUM(revenue) AS lifetime_gross_sales FROM shopify_sales WHERE sale_date < CURRENT_DATE GROUP BY 1 ), lifetime_returns AS ( SELECT sku_group, SUM(qty) AS lifetime_return_qty FROM shopify_returns WHERE order_date < CURRENT_DATE GROUP BY 1 ), lifetime_performance AS ( SELECT ls.sku_group, ls.lifetime_sold_qty, ls.lifetime_gross_sales, COALESCE( lr.lifetime_return_qty, 0 ) AS lifetime_return_qty, cm.cogs, ls.lifetime_sold_qty * COALESCE(cm.cogs, 0) AS lifetime_cogs_sold, ls.lifetime_gross_sales - ( ls.lifetime_sold_qty * COALESCE(cm.cogs, 0) ) AS lifetime_margin, ROUND( ( ls.lifetime_gross_sales - ( ls.lifetime_sold_qty * COALESCE(cm.cogs, 0) ) ) / NULLIF(ls.lifetime_gross_sales, 0), 4 ) AS lifetime_gm_pct, ROUND( COALESCE( COALESCE(lr.lifetime_return_qty, 0) * 100.0 / NULLIF(ls.lifetime_sold_qty, 0), 0 ), 2 ) AS lifetime_return_pct FROM lifetime_sales ls LEFT JOIN lifetime_returns lr ON lr.sku_group = ls.sku_group LEFT JOIN cogs_map cm ON cm.sku_group = ls.sku_group ), base_output AS ( SELECT p.sku_group, g.l1_category, g.category, s.start_date, p.nc_days, p.total_sales_nc_days, p.total_revenue_nc AS revenue_nc, p.total_returns_nc AS return_qty_nc, lp.lifetime_sold_qty AS sold_qty, lp.lifetime_gross_sales AS revenue, lp.lifetime_return_qty AS return_qty, lp.lifetime_sold_qty, lp.lifetime_gross_sales, lp.lifetime_return_qty, lp.lifetime_return_pct AS return_pct, ROUND(p.xs_ros, 3) AS xs_ros, ROUND(p.s_ros, 3) AS s_ros, ROUND(p.m_ros, 3) AS m_ros, ROUND(p.l_ros, 3) AS l_ros, ROUND(p.xl_ros, 3) AS xl_ros, ROUND(p.xxl_ros, 3) AS xxl_ros, ROUND(p.xl3_ros, 3) AS xl3_ros, ROUND(p.xl4_ros, 3) AS xl4_ros, ROUND(p.xl5_ros, 3) AS xl5_ros, ROUND(p.xl6_ros, 3) AS xl6_ros, ROUND(p.xl7_ros, 3) AS xl7_ros, ROUND(p.xl8_ros, 3) AS xl8_ros, ROUND(p.sku_ros, 3) AS sku_ros, ROUND( ri.avg_category_l1_ros, 3 ) AS avg_category_l1_ros, ri.sku_ros_index, ROUND( a.avg_inventory_nc_days, 2 ) AS avg_inventory_nc_days, ROUND( p.total_sales_nc_days / NULLIF(a.avg_inventory_nc_days, 0), 4 ) AS sku_str, lp.cogs, lp.lifetime_cogs_sold AS cogs_sold, lp.lifetime_margin AS margin, lp.lifetime_gm_pct AS gm_pct FROM sku_level_output p JOIN start_dt s ON s.sku_group = p.sku_group JOIN sku_grp_map g ON g.sku_group = p.sku_group LEFT JOIN avg_nc_inventory a ON a.sku_group = p.sku_group LEFT JOIN category_ros_index ri ON ri.sku_group = p.sku_group LEFT JOIN lifetime_performance lp ON lp.sku_group = p.sku_group ), category_return_benchmark AS ( SELECT b.*, ROUND( 100.0 * SUM(lifetime_return_qty) OVER ( PARTITION BY category, l1_category ) / NULLIF( SUM(lifetime_sold_qty) OVER ( PARTITION BY category, l1_category ), 0 ), 2 ) AS avg_category_l1_return_pct FROM base_output b ) SELECT b.*, CASE WHEN ( ( UPPER(TRIM(b.l1_category)) = \'SNITCH\' AND b.sku_ros > 10 ) OR ( UPPER(TRIM(b.l1_category)) IN (\'PLUS\',\'LUXE\') AND b.sku_ros > 5 ) ) AND b.gm_pct > 0.55 AND b.return_pct < b.avg_category_l1_return_pct THEN \'Repeat\' ELSE \'No Repeat\' END AS R1, CASE WHEN b.sku_ros_index > 1 AND b.gm_pct > 0.52 AND b.return_pct < b.avg_category_l1_return_pct THEN \'Repeat\' ELSE \'No Repeat\' END AS R2 FROM category_return_benchmark b ORDER BY b.sku_group ; create or replace table snitch_db.maplemonk.sru_repeats_offline as WITH inventory_base AS ( SELECT DATE::DATE AS DATE, TRIM(CAST(BRANCH_CODE AS VARCHAR)) AS BRANCH_CODE, UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, FIRST_ORDER_DATE::DATE AS FIRST_ORDER_DATE, NEW_CATEGORY, COALESCE(XS_UNITS, 0) AS XS_UNITS, COALESCE(S_UNITS, 0) AS S_UNITS, COALESCE(M_UNITS, 0) AS M_UNITS, COALESCE(L_UNITS, 0) AS L_UNITS, COALESCE(XL_UNITS, 0) AS XL_UNITS, COALESCE(XXL_UNITS, 0) AS XXL_UNITS, COALESCE(XL3_UNITS, 0) AS XL3_UNITS, COALESCE(XL4_UNITS, 0) AS XL4_UNITS, COALESCE(XL5_UNITS, 0) AS XL5_UNITS, COALESCE(XL6_UNITS, 0) AS XL6_UNITS FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER_DAILY_REPORT_1 WHERE FIRST_ORDER_DATE >= \'2025-10-01\' AND NEW_CATEGORY IN ( \'Blazers\', \'Cargo Pants\', \'Chinos\', \'Hoodies\', \'Jackets\', \'Jeans\', \'Joggers & Trackpants\', \'Overshirt\', \'Shirts\', \'Shorts\', \'Sweaters\', \'Sweatshirts\', \'Trousers\', \'T-Shirts\' ) AND SKU_GROUP IS NOT NULL AND BRANCH_CODE IS NOT NULL ), store_sku_master AS ( SELECT BRANCH_CODE, SKU_GROUP, MIN(FIRST_ORDER_DATE) AS FIRST_ORDER_DATE, MAX(NEW_CATEGORY) AS NEW_CATEGORY FROM inventory_base GROUP BY BRANCH_CODE, SKU_GROUP ), sales_base AS ( SELECT TRIM(CAST(BRANCH_CODE AS VARCHAR)) AS BRANCH_CODE, UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, ORDER_DATE::DATE AS ORDER_DATE, CASE WHEN UPPER(TRIM(REGEXP_SUBSTR(SKU, \'[^-]+$\'))) = \'28\' THEN \'XS\' WHEN UPPER(TRIM(REGEXP_SUBSTR(SKU, \'[^-]+$\'))) = \'30\' THEN \'S\' WHEN UPPER(TRIM(REGEXP_SUBSTR(SKU, \'[^-]+$\'))) = \'32\' THEN \'M\' WHEN UPPER(TRIM(REGEXP_SUBSTR(SKU, \'[^-]+$\'))) = \'34\' THEN \'L\' WHEN UPPER(TRIM(REGEXP_SUBSTR(SKU, \'[^-]+$\'))) = \'36\' THEN \'XL\' WHEN UPPER(TRIM(REGEXP_SUBSTR(SKU, \'[^-]+$\'))) = \'38\' THEN \'XXL\' WHEN UPPER(TRIM(REGEXP_SUBSTR(SKU, \'[^-]+$\'))) = \'40\' THEN \'3XL\' WHEN UPPER(TRIM(REGEXP_SUBSTR(SKU, \'[^-]+$\'))) = \'42\' THEN \'4XL\' WHEN UPPER(TRIM(REGEXP_SUBSTR(SKU, \'[^-]+$\'))) = \'44\' THEN \'5XL\' WHEN UPPER(TRIM(REGEXP_SUBSTR(SKU, \'[^-]+$\'))) = \'46\' THEN \'6XL\' WHEN UPPER(TRIM(REGEXP_SUBSTR(SKU, \'[^-]+$\'))) = \'XS\' THEN \'XS\' WHEN UPPER(TRIM(REGEXP_SUBSTR(SKU, \'[^-]+$\'))) = \'S\' THEN \'S\' WHEN UPPER(TRIM(REGEXP_SUBSTR(SKU, \'[^-]+$\'))) = \'M\' THEN \'M\' WHEN UPPER(TRIM(REGEXP_SUBSTR(SKU, \'[^-]+$\'))) = \'L\' THEN \'L\' WHEN UPPER(TRIM(REGEXP_SUBSTR(SKU, \'[^-]+$\'))) = \'XL\' THEN \'XL\' WHEN UPPER(TRIM(REGEXP_SUBSTR(SKU, \'[^-]+$\'))) IN (\'XXL\', \'2XL\') THEN \'XXL\' WHEN UPPER(TRIM(REGEXP_SUBSTR(SKU, \'[^-]+$\'))) = \'3XL\' THEN \'3XL\' WHEN UPPER(TRIM(REGEXP_SUBSTR(SKU, \'[^-]+$\'))) = \'4XL\' THEN \'4XL\' WHEN UPPER(TRIM(REGEXP_SUBSTR(SKU, \'[^-]+$\'))) = \'5XL\' THEN \'5XL\' WHEN UPPER(TRIM(REGEXP_SUBSTR(SKU, \'[^-]+$\'))) = \'6XL\' THEN \'6XL\' ELSE UPPER(TRIM(REGEXP_SUBSTR(SKU, \'[^-]+$\'))) END AS SIZE, SUM(SUBORDER_QUANTITY) AS SALES_QTY FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE WHERE COALESCE(DOC_PREFIX, \'\') NOT IN (\'OMS\', \'QCOM\') AND BRANCH_CODE NOT IN ( 157, 152, 146, 104, 155, 123, 139, 154, 120, 94, 76, 98 ) AND ORDER_DATE::DATE >= \'2025-10-01\' AND SKU_GROUP IS NOT NULL AND BRANCH_CODE IS NOT NULL GROUP BY 1,2,3,4 ), initial_sales AS ( SELECT m.BRANCH_CODE, m.SKU_GROUP, m.NEW_CATEGORY, m.FIRST_ORDER_DATE, COALESCE( SUM( CASE WHEN s.ORDER_DATE >= m.FIRST_ORDER_DATE AND s.ORDER_DATE < DATEADD(DAY, 7, m.FIRST_ORDER_DATE) THEN s.SALES_QTY ELSE 0 END ), 0 ) AS SALES_FIRST_7_DAYS, COALESCE( SUM( CASE WHEN s.ORDER_DATE >= m.FIRST_ORDER_DATE AND s.ORDER_DATE < DATEADD(DAY, 15, m.FIRST_ORDER_DATE) THEN s.SALES_QTY ELSE 0 END ), 0 ) AS SALES_FIRST_15_DAYS FROM store_sku_master m LEFT JOIN sales_base s ON m.BRANCH_CODE = s.BRANCH_CODE AND m.SKU_GROUP = s.SKU_GROUP AND s.ORDER_DATE >= m.FIRST_ORDER_DATE AND s.ORDER_DATE < DATEADD(DAY, 15, m.FIRST_ORDER_DATE) GROUP BY m.BRANCH_CODE, m.SKU_GROUP, m.NEW_CATEGORY, m.FIRST_ORDER_DATE ), ros_1 AS ( SELECT *, ROUND( SALES_FIRST_7_DAYS / 7.0, 4 ) AS ROS_1_7D, ROUND( SALES_FIRST_15_DAYS / 15.0, 4 ) AS ROS_1_15D FROM initial_sales ), daily_status AS ( SELECT *, CASE WHEN UPPER(SKU_GROUP) LIKE \'4MBG%\' OR UPPER(SKU_GROUP) LIKE \'4BRN%\' OR UPPER(SKU_GROUP) LIKE \'4BPL%\' OR UPPER(SKU_GROUP) LIKE \'4BTR%\' OR UPPER(SKU_GROUP) LIKE \'4BCH%\' OR UPPER(SKU_GROUP) LIKE \'4BJE%\' OR UPPER(SKU_GROUP) LIKE \'4BJK%\' OR UPPER(SKU_GROUP) LIKE \'4BSW%\' OR UPPER(SKU_GROUP) LIKE \'4BHD%\' OR UPPER(SKU_GROUP) LIKE \'4BOS%\' OR UPPER(SKU_GROUP) LIKE \'4BSHS%\' OR UPPER(SKU_GROUP) LIKE \'4BSFS%\' OR UPPER(SKU_GROUP) LIKE \'4BSH%\' OR UPPER(SKU_GROUP) LIKE \'4BBL%\' OR UPPER(SKU_GROUP) LIKE \'4BCA%\' OR UPPER(SKU_GROUP) LIKE \'4BSWT%\' OR UPPER(SKU_GROUP) LIKE \'4BCD%\' OR UPPER(SKU_GROUP) LIKE \'4BJO%\' THEN CASE WHEN ( CASE WHEN XL3_UNITS > 0 THEN 1 ELSE 0 END + CASE WHEN XL4_UNITS > 0 THEN 1 ELSE 0 END + CASE WHEN XL5_UNITS > 0 THEN 1 ELSE 0 END + CASE WHEN XL6_UNITS > 0 THEN 1 ELSE 0 END ) >= 3 THEN 1 ELSE 0 END ELSE CASE WHEN ( CASE WHEN S_UNITS > 0 THEN 1 ELSE 0 END + CASE WHEN M_UNITS > 0 THEN 1 ELSE 0 END + CASE WHEN L_UNITS > 0 THEN 1 ELSE 0 END + CASE WHEN XL_UNITS > 0 THEN 1 ELSE 0 END ) >= 3 AND ( CASE WHEN XS_UNITS > 0 THEN 1 ELSE 0 END + CASE WHEN S_UNITS > 0 THEN 1 ELSE 0 END + CASE WHEN M_UNITS > 0 THEN 1 ELSE 0 END + CASE WHEN L_UNITS > 0 THEN 1 ELSE 0 END + CASE WHEN XL_UNITS > 0 THEN 1 ELSE 0 END + CASE WHEN XXL_UNITS > 0 THEN 1 ELSE 0 END ) >= 4 THEN 1 ELSE 0 END END AS IS_FULL_SIZE FROM inventory_base ), previous_status AS ( SELECT *, LAG(IS_FULL_SIZE) OVER ( PARTITION BY BRANCH_CODE, SKU_GROUP ORDER BY DATE ) AS PREV_FULL_SIZE, LAG(DATE) OVER ( PARTITION BY BRANCH_CODE, SKU_GROUP ORDER BY DATE ) AS PREV_DATE FROM daily_status ), allocation_start AS ( SELECT *, CASE WHEN IS_FULL_SIZE = 1 AND ( PREV_FULL_SIZE IS NULL OR PREV_FULL_SIZE = 0 OR DATEDIFF(DAY, PREV_DATE, DATE) > 1 ) THEN 1 ELSE 0 END AS NEW_ALLOCATION FROM previous_status ), allocation_numbered AS ( SELECT *, SUM(NEW_ALLOCATION) OVER ( PARTITION BY BRANCH_CODE, SKU_GROUP ORDER BY DATE ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS ALLOCATION_NUMBER FROM allocation_start ), allocation_periods AS ( SELECT BRANCH_CODE, SKU_GROUP, NEW_CATEGORY, ALLOCATION_NUMBER, MIN(DATE) AS FULL_SIZE_START_DATE, MAX(DATE) AS LAST_FULL_SIZE_DATE, COUNT(DISTINCT DATE) AS FULL_SIZE_DAYS FROM allocation_numbered WHERE IS_FULL_SIZE = 1 AND ALLOCATION_NUMBER BETWEEN 1 AND 4 GROUP BY BRANCH_CODE, SKU_GROUP, NEW_CATEGORY, ALLOCATION_NUMBER ), allocation_windows AS ( SELECT *, DATEADD( DAY, 1, LAST_FULL_SIZE_DATE ) AS FULL_SIZE_END_DATE FROM allocation_periods ), allocation_sales AS ( SELECT a.BRANCH_CODE, a.SKU_GROUP, a.NEW_CATEGORY, a.ALLOCATION_NUMBER, a.FULL_SIZE_START_DATE, a.LAST_FULL_SIZE_DATE, a.FULL_SIZE_END_DATE, a.FULL_SIZE_DAYS, COALESCE( SUM(s.SALES_QTY), 0 ) AS SALES_DURING_FULL_SIZE, COALESCE( SUM(CASE WHEN s.SIZE = \'XS\' THEN s.SALES_QTY ELSE 0 END), 0 ) AS XS_SALES, COALESCE( SUM(CASE WHEN s.SIZE = \'S\' THEN s.SALES_QTY ELSE 0 END), 0 ) AS S_SALES, COALESCE( SUM(CASE WHEN s.SIZE = \'M\' THEN s.SALES_QTY ELSE 0 END), 0 ) AS M_SALES, COALESCE( SUM(CASE WHEN s.SIZE = \'L\' THEN s.SALES_QTY ELSE 0 END), 0 ) AS L_SALES, COALESCE( SUM(CASE WHEN s.SIZE = \'XL\' THEN s.SALES_QTY ELSE 0 END), 0 ) AS XL_SALES, COALESCE( SUM(CASE WHEN s.SIZE = \'XXL\' THEN s.SALES_QTY ELSE 0 END), 0 ) AS XXL_SALES, COALESCE( SUM(CASE WHEN s.SIZE = \'3XL\' THEN s.SALES_QTY ELSE 0 END), 0 ) AS XL3_SALES, COALESCE( SUM(CASE WHEN s.SIZE = \'4XL\' THEN s.SALES_QTY ELSE 0 END), 0 ) AS XL4_SALES, COALESCE( SUM(CASE WHEN s.SIZE = \'5XL\' THEN s.SALES_QTY ELSE 0 END), 0 ) AS XL5_SALES, COALESCE( SUM(CASE WHEN s.SIZE = \'6XL\' THEN s.SALES_QTY ELSE 0 END), 0 ) AS XL6_SALES FROM allocation_windows a LEFT JOIN sales_base s ON a.BRANCH_CODE = s.BRANCH_CODE AND a.SKU_GROUP = s.SKU_GROUP AND s.ORDER_DATE >= a.FULL_SIZE_START_DATE AND s.ORDER_DATE < a.FULL_SIZE_END_DATE GROUP BY a.BRANCH_CODE, a.SKU_GROUP, a.NEW_CATEGORY, a.ALLOCATION_NUMBER, a.FULL_SIZE_START_DATE, a.LAST_FULL_SIZE_DATE, a.FULL_SIZE_END_DATE, a.FULL_SIZE_DAYS ), allocation_closing_inventory AS ( SELECT a.BRANCH_CODE, a.SKU_GROUP, a.ALLOCATION_NUMBER, (COALESCE(i.XS_UNITS, 0) + COALESCE(i.S_UNITS, 0) + COALESCE(i.M_UNITS, 0) + COALESCE(i.L_UNITS, 0) + COALESCE(i.XL_UNITS, 0) + COALESCE(i.XXL_UNITS, 0) + COALESCE(i.XL3_UNITS, 0) + COALESCE(i.XL4_UNITS, 0) + COALESCE(i.XL5_UNITS, 0) + COALESCE(i.XL6_UNITS, 0)) AS CLOSING_INVENTORY FROM allocation_windows a LEFT JOIN inventory_base i ON i.BRANCH_CODE = a.BRANCH_CODE AND i.SKU_GROUP = a.SKU_GROUP AND i.DATE = a.LAST_FULL_SIZE_DATE ), allocation_ros AS ( SELECT a.*, ci.CLOSING_INVENTORY, ROUND(a.SALES_DURING_FULL_SIZE * 1.0 / NULLIF(ci.CLOSING_INVENTORY + a.SALES_DURING_FULL_SIZE, 0), 4) AS ALLOCATION_STR, ROUND( SALES_DURING_FULL_SIZE / NULLIF(FULL_SIZE_DAYS, 0), 4 ) AS ALLOCATION_ROS, ROUND( XS_SALES / NULLIF(FULL_SIZE_DAYS, 0), 4 ) AS XS_ROS, ROUND( S_SALES / NULLIF(FULL_SIZE_DAYS, 0), 4 ) AS S_ROS, ROUND( M_SALES / NULLIF(FULL_SIZE_DAYS, 0), 4 ) AS M_ROS, ROUND( L_SALES / NULLIF(FULL_SIZE_DAYS, 0), 4 ) AS L_ROS, ROUND( XL_SALES / NULLIF(FULL_SIZE_DAYS, 0), 4 ) AS XL_ROS, ROUND( XXL_SALES / NULLIF(FULL_SIZE_DAYS, 0), 4 ) AS XXL_ROS, ROUND( XL3_SALES / NULLIF(FULL_SIZE_DAYS, 0), 4 ) AS XL3_ROS, ROUND( XL4_SALES / NULLIF(FULL_SIZE_DAYS, 0), 4 ) AS XL4_ROS, ROUND( XL5_SALES / NULLIF(FULL_SIZE_DAYS, 0), 4 ) AS XL5_ROS, ROUND( XL6_SALES / NULLIF(FULL_SIZE_DAYS, 0), 4 ) AS XL6_ROS FROM allocation_sales a LEFT JOIN allocation_closing_inventory ci ON a.BRANCH_CODE = ci.BRANCH_CODE AND a.SKU_GROUP = ci.SKU_GROUP AND a.ALLOCATION_NUMBER = ci.ALLOCATION_NUMBER ), initial_sku_level AS ( SELECT SKU_GROUP, MAX(NEW_CATEGORY) AS NEW_CATEGORY, COUNT(DISTINCT BRANCH_CODE) AS STORE_COUNT, SUM(SALES_FIRST_7_DAYS) AS TOTAL_SALES_FIRST_7_DAYS, ROUND( AVG(ROS_1_7D), 4 ) AS AVG_ROS_1_7D, SUM(SALES_FIRST_15_DAYS) AS TOTAL_SALES_FIRST_15_DAYS, ROUND( AVG(ROS_1_15D), 4 ) AS AVG_ROS_1_15D FROM ros_1 GROUP BY SKU_GROUP ), allocation_sku_level AS ( SELECT SKU_GROUP, COUNT( DISTINCT CASE WHEN ALLOCATION_NUMBER = 1 THEN BRANCH_CODE END ) AS ALLOCATION_1_STORE_COUNT, SUM( CASE WHEN ALLOCATION_NUMBER = 1 THEN SALES_DURING_FULL_SIZE ELSE 0 END ) AS ALLOCATION_1_TOTAL_SALES, ROUND( AVG( CASE WHEN ALLOCATION_NUMBER = 1 THEN FULL_SIZE_DAYS END ), 2 ) AS ALLOCATION_1_FULL_SIZE_DAYS, ROUND( AVG( CASE WHEN ALLOCATION_NUMBER = 1 THEN ALLOCATION_ROS END ), 4 ) AS ALLOCATION_1_ROS, ROUND(AVG(CASE WHEN ALLOCATION_NUMBER = 1 THEN ALLOCATION_STR END), 4) AS ALLOCATION_1_STR, ROUND( AVG( CASE WHEN ALLOCATION_NUMBER = 1 THEN XS_ROS END ), 4 ) AS ALLOCATION_1_XS_ROS, ROUND( AVG( CASE WHEN ALLOCATION_NUMBER = 1 THEN S_ROS END ), 4 ) AS ALLOCATION_1_S_ROS, ROUND( AVG( CASE WHEN ALLOCATION_NUMBER = 1 THEN M_ROS END ), 4 ) AS ALLOCATION_1_M_ROS, ROUND( AVG( CASE WHEN ALLOCATION_NUMBER = 1 THEN L_ROS END ), 4 ) AS ALLOCATION_1_L_ROS, ROUND( AVG( CASE WHEN ALLOCATION_NUMBER = 1 THEN XL_ROS END ), 4 ) AS ALLOCATION_1_XL_ROS, ROUND( AVG( CASE WHEN ALLOCATION_NUMBER = 1 THEN XXL_ROS END ), 4 ) AS ALLOCATION_1_XXL_ROS, ROUND( AVG( CASE WHEN ALLOCATION_NUMBER = 1 THEN XL3_ROS END ), 4 ) AS ALLOCATION_1_3XL_ROS, ROUND( AVG( CASE WHEN ALLOCATION_NUMBER = 1 THEN XL4_ROS END ), 4 ) AS ALLOCATION_1_4XL_ROS, ROUND( AVG( CASE WHEN ALLOCATION_NUMBER = 1 THEN XL5_ROS END ), 4 ) AS ALLOCATION_1_5XL_ROS, ROUND( AVG( CASE WHEN ALLOCATION_NUMBER = 1 THEN XL6_ROS END ), 4 ) AS ALLOCATION_1_6XL_ROS, COUNT( DISTINCT CASE WHEN ALLOCATION_NUMBER = 2 THEN BRANCH_CODE END ) AS ALLOCATION_2_STORE_COUNT, SUM( CASE WHEN ALLOCATION_NUMBER = 2 THEN SALES_DURING_FULL_SIZE ELSE 0 END ) AS ALLOCATION_2_TOTAL_SALES, ROUND( AVG( CASE WHEN ALLOCATION_NUMBER = 2 THEN FULL_SIZE_DAYS END ), 2 ) AS ALLOCATION_2_FULL_SIZE_DAYS, ROUND( AVG( CASE WHEN ALLOCATION_NUMBER = 2 THEN ALLOCATION_ROS END ), 4 ) AS ALLOCATION_2_ROS, ROUND(AVG(CASE WHEN ALLOCATION_NUMBER = 2 THEN ALLOCATION_STR END), 4) AS ALLOCATION_2_STR, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 2 THEN XS_ROS END), 4 ) AS ALLOCATION_2_XS_ROS, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 2 THEN S_ROS END), 4 ) AS ALLOCATION_2_S_ROS, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 2 THEN M_ROS END), 4 ) AS ALLOCATION_2_M_ROS, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 2 THEN L_ROS END), 4 ) AS ALLOCATION_2_L_ROS, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 2 THEN XL_ROS END), 4 ) AS ALLOCATION_2_XL_ROS, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 2 THEN XXL_ROS END), 4 ) AS ALLOCATION_2_XXL_ROS, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 2 THEN XL3_ROS END), 4 ) AS ALLOCATION_2_3XL_ROS, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 2 THEN XL4_ROS END), 4 ) AS ALLOCATION_2_4XL_ROS, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 2 THEN XL5_ROS END), 4 ) AS ALLOCATION_2_5XL_ROS, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 2 THEN XL6_ROS END), 4 ) AS ALLOCATION_2_6XL_ROS, COUNT( DISTINCT CASE WHEN ALLOCATION_NUMBER = 3 THEN BRANCH_CODE END ) AS ALLOCATION_3_STORE_COUNT, SUM( CASE WHEN ALLOCATION_NUMBER = 3 THEN SALES_DURING_FULL_SIZE ELSE 0 END ) AS ALLOCATION_3_TOTAL_SALES, ROUND( AVG( CASE WHEN ALLOCATION_NUMBER = 3 THEN FULL_SIZE_DAYS END ), 2 ) AS ALLOCATION_3_FULL_SIZE_DAYS, ROUND( AVG( CASE WHEN ALLOCATION_NUMBER = 3 THEN ALLOCATION_ROS END ), 4 ) AS ALLOCATION_3_ROS, ROUND(AVG(CASE WHEN ALLOCATION_NUMBER = 3 THEN ALLOCATION_STR END), 4) AS ALLOCATION_3_STR, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 3 THEN XS_ROS END), 4 ) AS ALLOCATION_3_XS_ROS, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 3 THEN S_ROS END), 4 ) AS ALLOCATION_3_S_ROS, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 3 THEN M_ROS END), 4 ) AS ALLOCATION_3_M_ROS, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 3 THEN L_ROS END), 4 ) AS ALLOCATION_3_L_ROS, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 3 THEN XL_ROS END), 4 ) AS ALLOCATION_3_XL_ROS, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 3 THEN XXL_ROS END), 4 ) AS ALLOCATION_3_XXL_ROS, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 3 THEN XL3_ROS END), 4 ) AS ALLOCATION_3_3XL_ROS, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 3 THEN XL4_ROS END), 4 ) AS ALLOCATION_3_4XL_ROS, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 3 THEN XL5_ROS END), 4 ) AS ALLOCATION_3_5XL_ROS, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 3 THEN XL6_ROS END), 4 ) AS ALLOCATION_3_6XL_ROS, COUNT( DISTINCT CASE WHEN ALLOCATION_NUMBER = 4 THEN BRANCH_CODE END ) AS ALLOCATION_4_STORE_COUNT, SUM( CASE WHEN ALLOCATION_NUMBER = 4 THEN SALES_DURING_FULL_SIZE ELSE 0 END ) AS ALLOCATION_4_TOTAL_SALES, ROUND( AVG( CASE WHEN ALLOCATION_NUMBER = 4 THEN FULL_SIZE_DAYS END ), 2 ) AS ALLOCATION_4_FULL_SIZE_DAYS, ROUND( AVG( CASE WHEN ALLOCATION_NUMBER = 4 THEN ALLOCATION_ROS END ), 4 ) AS ALLOCATION_4_ROS, ROUND(AVG(CASE WHEN ALLOCATION_NUMBER = 4 THEN ALLOCATION_STR END), 4) AS ALLOCATION_4_STR, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 4 THEN XS_ROS END), 4 ) AS ALLOCATION_4_XS_ROS, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 4 THEN S_ROS END), 4 ) AS ALLOCATION_4_S_ROS, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 4 THEN M_ROS END), 4 ) AS ALLOCATION_4_M_ROS, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 4 THEN L_ROS END), 4 ) AS ALLOCATION_4_L_ROS, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 4 THEN XL_ROS END), 4 ) AS ALLOCATION_4_XL_ROS, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 4 THEN XXL_ROS END), 4 ) AS ALLOCATION_4_XXL_ROS, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 4 THEN XL3_ROS END), 4 ) AS ALLOCATION_4_3XL_ROS, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 4 THEN XL4_ROS END), 4 ) AS ALLOCATION_4_4XL_ROS, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 4 THEN XL5_ROS END), 4 ) AS ALLOCATION_4_5XL_ROS, ROUND( AVG(CASE WHEN ALLOCATION_NUMBER = 4 THEN XL6_ROS END), 4 ) AS ALLOCATION_4_6XL_ROS FROM allocation_ros GROUP BY SKU_GROUP ), sku_level AS ( SELECT i.SKU_GROUP, i.NEW_CATEGORY, i.STORE_COUNT, i.TOTAL_SALES_FIRST_7_DAYS, i.AVG_ROS_1_7D, i.TOTAL_SALES_FIRST_15_DAYS, i.AVG_ROS_1_15D, COALESCE(a.ALLOCATION_1_STORE_COUNT, 0) AS ALLOCATION_1_STORE_COUNT, a.ALLOCATION_1_TOTAL_SALES, a.ALLOCATION_1_FULL_SIZE_DAYS, a.ALLOCATION_1_ROS, a.ALLOCATION_1_STR, a.ALLOCATION_1_XS_ROS, a.ALLOCATION_1_S_ROS, a.ALLOCATION_1_M_ROS, a.ALLOCATION_1_L_ROS, a.ALLOCATION_1_XL_ROS, a.ALLOCATION_1_XXL_ROS, a.ALLOCATION_1_3XL_ROS, a.ALLOCATION_1_4XL_ROS, a.ALLOCATION_1_5XL_ROS, a.ALLOCATION_1_6XL_ROS, COALESCE(a.ALLOCATION_2_STORE_COUNT, 0) AS ALLOCATION_2_STORE_COUNT, a.ALLOCATION_2_TOTAL_SALES, a.ALLOCATION_2_FULL_SIZE_DAYS, a.ALLOCATION_2_ROS, a.ALLOCATION_2_STR, a.ALLOCATION_2_XS_ROS, a.ALLOCATION_2_S_ROS, a.ALLOCATION_2_M_ROS, a.ALLOCATION_2_L_ROS, a.ALLOCATION_2_XL_ROS, a.ALLOCATION_2_XXL_ROS, a.ALLOCATION_2_3XL_ROS, a.ALLOCATION_2_4XL_ROS, a.ALLOCATION_2_5XL_ROS, a.ALLOCATION_2_6XL_ROS, COALESCE(a.ALLOCATION_3_STORE_COUNT, 0) AS ALLOCATION_3_STORE_COUNT, a.ALLOCATION_3_TOTAL_SALES, a.ALLOCATION_3_FULL_SIZE_DAYS, a.ALLOCATION_3_ROS, a.ALLOCATION_3_STR, a.ALLOCATION_3_XS_ROS, a.ALLOCATION_3_S_ROS, a.ALLOCATION_3_M_ROS, a.ALLOCATION_3_L_ROS, a.ALLOCATION_3_XL_ROS, a.ALLOCATION_3_XXL_ROS, a.ALLOCATION_3_3XL_ROS, a.ALLOCATION_3_4XL_ROS, a.ALLOCATION_3_5XL_ROS, a.ALLOCATION_3_6XL_ROS, COALESCE(a.ALLOCATION_4_STORE_COUNT, 0) AS ALLOCATION_4_STORE_COUNT, a.ALLOCATION_4_TOTAL_SALES, a.ALLOCATION_4_FULL_SIZE_DAYS, a.ALLOCATION_4_ROS, a.ALLOCATION_4_STR, a.ALLOCATION_4_XS_ROS, a.ALLOCATION_4_S_ROS, a.ALLOCATION_4_M_ROS, a.ALLOCATION_4_L_ROS, a.ALLOCATION_4_XL_ROS, a.ALLOCATION_4_XXL_ROS, a.ALLOCATION_4_3XL_ROS, a.ALLOCATION_4_4XL_ROS, a.ALLOCATION_4_5XL_ROS, a.ALLOCATION_4_6XL_ROS FROM initial_sku_level i LEFT JOIN allocation_sku_level a ON i.SKU_GROUP = a.SKU_GROUP ), final_size_ros AS ( SELECT *, ROUND( ( ALLOCATION_1_STORE_COUNT * COALESCE(ALLOCATION_1_ROS, 0) + ALLOCATION_2_STORE_COUNT * COALESCE(ALLOCATION_2_ROS, 0) + ALLOCATION_3_STORE_COUNT * COALESCE(ALLOCATION_3_ROS, 0) + ALLOCATION_4_STORE_COUNT * COALESCE(ALLOCATION_4_ROS, 0) ) / NULLIF( ALLOCATION_1_STORE_COUNT + ALLOCATION_2_STORE_COUNT + ALLOCATION_3_STORE_COUNT + ALLOCATION_4_STORE_COUNT, 0 ), 4 ) AS FINAL_ROS, ROUND( ( ALLOCATION_1_STORE_COUNT * COALESCE(ALLOCATION_1_STR, 0) + ALLOCATION_2_STORE_COUNT * COALESCE(ALLOCATION_2_STR, 0) + ALLOCATION_3_STORE_COUNT * COALESCE(ALLOCATION_3_STR, 0) + ALLOCATION_4_STORE_COUNT * COALESCE(ALLOCATION_4_STR, 0)) / NULLIF(ALLOCATION_1_STORE_COUNT + ALLOCATION_2_STORE_COUNT + ALLOCATION_3_STORE_COUNT + ALLOCATION_4_STORE_COUNT, 0), 4 ) AS FINAL_STR, ROUND( ( ALLOCATION_1_STORE_COUNT * COALESCE(ALLOCATION_1_XS_ROS, 0) + ALLOCATION_2_STORE_COUNT * COALESCE(ALLOCATION_2_XS_ROS, 0) + ALLOCATION_3_STORE_COUNT * COALESCE(ALLOCATION_3_XS_ROS, 0) + ALLOCATION_4_STORE_COUNT * COALESCE(ALLOCATION_4_XS_ROS, 0) ) / NULLIF( ALLOCATION_1_STORE_COUNT + ALLOCATION_2_STORE_COUNT + ALLOCATION_3_STORE_COUNT + ALLOCATION_4_STORE_COUNT, 0 ), 4 ) AS FINAL_XS_ROS, ROUND( ( ALLOCATION_1_STORE_COUNT * COALESCE(ALLOCATION_1_S_ROS, 0) + ALLOCATION_2_STORE_COUNT * COALESCE(ALLOCATION_2_S_ROS, 0) + ALLOCATION_3_STORE_COUNT * COALESCE(ALLOCATION_3_S_ROS, 0) + ALLOCATION_4_STORE_COUNT * COALESCE(ALLOCATION_4_S_ROS, 0) ) / NULLIF( ALLOCATION_1_STORE_COUNT + ALLOCATION_2_STORE_COUNT + ALLOCATION_3_STORE_COUNT + ALLOCATION_4_STORE_COUNT, 0 ), 4 ) AS FINAL_S_ROS, ROUND( ( ALLOCATION_1_STORE_COUNT * COALESCE(ALLOCATION_1_M_ROS, 0) + ALLOCATION_2_STORE_COUNT * COALESCE(ALLOCATION_2_M_ROS, 0) + ALLOCATION_3_STORE_COUNT * COALESCE(ALLOCATION_3_M_ROS, 0) + ALLOCATION_4_STORE_COUNT * COALESCE(ALLOCATION_4_M_ROS, 0) ) / NULLIF( ALLOCATION_1_STORE_COUNT + ALLOCATION_2_STORE_COUNT + ALLOCATION_3_STORE_COUNT + ALLOCATION_4_STORE_COUNT, 0 ), 4 ) AS FINAL_M_ROS, ROUND( ( ALLOCATION_1_STORE_COUNT * COALESCE(ALLOCATION_1_L_ROS, 0) + ALLOCATION_2_STORE_COUNT * COALESCE(ALLOCATION_2_L_ROS, 0) + ALLOCATION_3_STORE_COUNT * COALESCE(ALLOCATION_3_L_ROS, 0) + ALLOCATION_4_STORE_COUNT * COALESCE(ALLOCATION_4_L_ROS, 0) ) / NULLIF( ALLOCATION_1_STORE_COUNT + ALLOCATION_2_STORE_COUNT + ALLOCATION_3_STORE_COUNT + ALLOCATION_4_STORE_COUNT, 0 ), 4 ) AS FINAL_L_ROS, ROUND( ( ALLOCATION_1_STORE_COUNT * COALESCE(ALLOCATION_1_XL_ROS, 0) + ALLOCATION_2_STORE_COUNT * COALESCE(ALLOCATION_2_XL_ROS, 0) + ALLOCATION_3_STORE_COUNT * COALESCE(ALLOCATION_3_XL_ROS, 0) + ALLOCATION_4_STORE_COUNT * COALESCE(ALLOCATION_4_XL_ROS, 0) ) / NULLIF( ALLOCATION_1_STORE_COUNT + ALLOCATION_2_STORE_COUNT + ALLOCATION_3_STORE_COUNT + ALLOCATION_4_STORE_COUNT, 0 ), 4 ) AS FINAL_XL_ROS, ROUND( ( ALLOCATION_1_STORE_COUNT * COALESCE(ALLOCATION_1_XXL_ROS, 0) + ALLOCATION_2_STORE_COUNT * COALESCE(ALLOCATION_2_XXL_ROS, 0) + ALLOCATION_3_STORE_COUNT * COALESCE(ALLOCATION_3_XXL_ROS, 0) + ALLOCATION_4_STORE_COUNT * COALESCE(ALLOCATION_4_XXL_ROS, 0) ) / NULLIF( ALLOCATION_1_STORE_COUNT + ALLOCATION_2_STORE_COUNT + ALLOCATION_3_STORE_COUNT + ALLOCATION_4_STORE_COUNT, 0 ), 4 ) AS FINAL_XXL_ROS, ROUND( ( ALLOCATION_1_STORE_COUNT * COALESCE(ALLOCATION_1_3XL_ROS, 0) + ALLOCATION_2_STORE_COUNT * COALESCE(ALLOCATION_2_3XL_ROS, 0) + ALLOCATION_3_STORE_COUNT * COALESCE(ALLOCATION_3_3XL_ROS, 0) + ALLOCATION_4_STORE_COUNT * COALESCE(ALLOCATION_4_3XL_ROS, 0) ) / NULLIF( ALLOCATION_1_STORE_COUNT + ALLOCATION_2_STORE_COUNT + ALLOCATION_3_STORE_COUNT + ALLOCATION_4_STORE_COUNT, 0 ), 4 ) AS FINAL_3XL_ROS, ROUND( ( ALLOCATION_1_STORE_COUNT * COALESCE(ALLOCATION_1_4XL_ROS, 0) + ALLOCATION_2_STORE_COUNT * COALESCE(ALLOCATION_2_4XL_ROS, 0) + ALLOCATION_3_STORE_COUNT * COALESCE(ALLOCATION_3_4XL_ROS, 0) + ALLOCATION_4_STORE_COUNT * COALESCE(ALLOCATION_4_4XL_ROS, 0) ) / NULLIF( ALLOCATION_1_STORE_COUNT + ALLOCATION_2_STORE_COUNT + ALLOCATION_3_STORE_COUNT + ALLOCATION_4_STORE_COUNT, 0 ), 4 ) AS FINAL_4XL_ROS, ROUND( ( ALLOCATION_1_STORE_COUNT * COALESCE(ALLOCATION_1_5XL_ROS, 0) + ALLOCATION_2_STORE_COUNT * COALESCE(ALLOCATION_2_5XL_ROS, 0) + ALLOCATION_3_STORE_COUNT * COALESCE(ALLOCATION_3_5XL_ROS, 0) + ALLOCATION_4_STORE_COUNT * COALESCE(ALLOCATION_4_5XL_ROS, 0) ) / NULLIF( ALLOCATION_1_STORE_COUNT + ALLOCATION_2_STORE_COUNT + ALLOCATION_3_STORE_COUNT + ALLOCATION_4_STORE_COUNT, 0 ), 4 ) AS FINAL_5XL_ROS, ROUND( ( ALLOCATION_1_STORE_COUNT * COALESCE(ALLOCATION_1_6XL_ROS, 0) + ALLOCATION_2_STORE_COUNT * COALESCE(ALLOCATION_2_6XL_ROS, 0) + ALLOCATION_3_STORE_COUNT * COALESCE(ALLOCATION_3_6XL_ROS, 0) + ALLOCATION_4_STORE_COUNT * COALESCE(ALLOCATION_4_6XL_ROS, 0) ) / NULLIF( ALLOCATION_1_STORE_COUNT + ALLOCATION_2_STORE_COUNT + ALLOCATION_3_STORE_COUNT + ALLOCATION_4_STORE_COUNT, 0 ), 4 ) AS FINAL_6XL_ROS FROM sku_level ), lifetime_gm AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, max(cogs_price) as cogs, SUM(SELLING_PRICE) AS LIFETIME_REVENUE, SUM( COALESCE(SUBORDER_QUANTITY, 0) * COALESCE(COGS_PRICE, 0) ) AS LIFETIME_COGS, ROUND( ( SUM(SELLING_PRICE) - SUM( COALESCE(SUBORDER_QUANTITY, 0) * COALESCE(COGS_PRICE, 0) ) ) / NULLIF(SUM(SELLING_PRICE), 0), 4 ) AS LIFETIME_GM_PCT FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE WHERE COALESCE(DOC_PREFIX, \'\') NOT IN (\'OMS\', \'QCOM\') AND BRANCH_CODE NOT IN ( 157, 152, 146, 104, 155, 123, 139, 154, 120, 94, 76, 98 ) AND SKU_GROUP IS NOT NULL AND BRANCH_CODE IS NOT NULL GROUP BY 1 ), meta_mapping AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, MAX(L1_CATEGORY) AS L1_CATEGORY, MAX(META1) AS META1, MAX(META2) AS META2, MAX(META3) AS META3 FROM SNITCH_DB.MAPLEMONK.META_MAPPING_COGS_SKU WHERE SKU_GROUP IS NOT NULL GROUP BY 1 ), total_stores AS ( SELECT COUNT(DISTINCT BRANCH_CODE) AS TOTAL_STORE_COUNT FROM inventory_base ) SELECT f.SKU_GROUP, f.NEW_CATEGORY, mm.L1_CATEGORY, mm.META1, mm.META2, mm.META3, f.STORE_COUNT, f.TOTAL_SALES_FIRST_7_DAYS, f.AVG_ROS_1_7D, f.TOTAL_SALES_FIRST_15_DAYS, f.AVG_ROS_1_15D, f.ALLOCATION_1_STORE_COUNT, f.ALLOCATION_1_TOTAL_SALES, f.ALLOCATION_1_FULL_SIZE_DAYS, f.ALLOCATION_1_ROS, f.ALLOCATION_1_STR, f.ALLOCATION_1_XS_ROS, f.ALLOCATION_1_S_ROS, f.ALLOCATION_1_M_ROS, f.ALLOCATION_1_L_ROS, f.ALLOCATION_1_XL_ROS, f.ALLOCATION_1_XXL_ROS, f.ALLOCATION_1_3XL_ROS, f.ALLOCATION_1_4XL_ROS, f.ALLOCATION_1_5XL_ROS, f.ALLOCATION_1_6XL_ROS, f.ALLOCATION_2_STORE_COUNT, f.ALLOCATION_2_TOTAL_SALES, f.ALLOCATION_2_FULL_SIZE_DAYS, f.ALLOCATION_2_ROS, f.ALLOCATION_2_STR, f.ALLOCATION_2_XS_ROS, f.ALLOCATION_2_S_ROS, f.ALLOCATION_2_M_ROS, f.ALLOCATION_2_L_ROS, f.ALLOCATION_2_XL_ROS, f.ALLOCATION_2_XXL_ROS, f.ALLOCATION_2_3XL_ROS, f.ALLOCATION_2_4XL_ROS, f.ALLOCATION_2_5XL_ROS, f.ALLOCATION_2_6XL_ROS, f.ALLOCATION_3_STORE_COUNT, f.ALLOCATION_3_TOTAL_SALES, f.ALLOCATION_3_FULL_SIZE_DAYS, f.ALLOCATION_3_ROS, f.ALLOCATION_3_STR, f.ALLOCATION_3_XS_ROS, f.ALLOCATION_3_S_ROS, f.ALLOCATION_3_M_ROS, f.ALLOCATION_3_L_ROS, f.ALLOCATION_3_XL_ROS, f.ALLOCATION_3_XXL_ROS, f.ALLOCATION_3_3XL_ROS, f.ALLOCATION_3_4XL_ROS, f.ALLOCATION_3_5XL_ROS, f.ALLOCATION_3_6XL_ROS, f.ALLOCATION_4_STORE_COUNT, f.ALLOCATION_4_TOTAL_SALES, f.ALLOCATION_4_FULL_SIZE_DAYS, f.ALLOCATION_4_ROS, f.ALLOCATION_4_STR, f.ALLOCATION_4_XS_ROS, f.ALLOCATION_4_S_ROS, f.ALLOCATION_4_M_ROS, f.ALLOCATION_4_L_ROS, f.ALLOCATION_4_XL_ROS, f.ALLOCATION_4_XXL_ROS, f.ALLOCATION_4_3XL_ROS, f.ALLOCATION_4_4XL_ROS, f.ALLOCATION_4_5XL_ROS, f.ALLOCATION_4_6XL_ROS, f.FINAL_ROS, ROUND( AVG(f.FINAL_ROS) OVER ( PARTITION BY f.NEW_CATEGORY, mm.L1_CATEGORY ), 4 ) AS AVG_CATEGORY_FINAL_ROS, ROUND( f.FINAL_ROS / NULLIF( AVG(f.FINAL_ROS) OVER ( PARTITION BY f.NEW_CATEGORY, mm.L1_CATEGORY ), 0 ), 4 ) AS ROS_INDEX, f.FINAL_STR, f.FINAL_XS_ROS, f.FINAL_S_ROS, f.FINAL_M_ROS, f.FINAL_L_ROS, f.FINAL_XL_ROS, f.FINAL_XXL_ROS, f.FINAL_3XL_ROS, f.FINAL_4XL_ROS, f.FINAL_5XL_ROS, f.FINAL_6XL_ROS, lg.LIFETIME_REVENUE, lg.COGS, lg.LIFETIME_GM_PCT, CASE WHEN lg.LIFETIME_GM_PCT >= 0.60 AND COALESCE(f.ALLOCATION_1_STORE_COUNT, 0) > 0 AND COALESCE(f.ALLOCATION_2_STORE_COUNT, 0) > 0 AND COALESCE(f.ALLOCATION_3_STORE_COUNT, 0) > 0 AND COALESCE(f.ALLOCATION_4_STORE_COUNT, 0) > 0 AND ( ( UPPER(TRIM(mm.L1_CATEGORY)) = \'SNITCH\' AND f.FINAL_ROS > 0.5 AND f.STORE_COUNT >= ts.TOTAL_STORE_COUNT * 0.50 ) OR ( UPPER(TRIM(mm.L1_CATEGORY)) = \'PLUS\' AND f.FINAL_ROS > 0.2 AND f.STORE_COUNT > 20 ) OR ( UPPER(TRIM(mm.L1_CATEGORY)) = \'LUXE\' AND f.FINAL_ROS > 0.2 AND f.STORE_COUNT > 20 ) ) THEN \'REPEAT\' ELSE \'NO REPEAT\' END AS R1, CASE WHEN lg.LIFETIME_GM_PCT >= 0.55 AND f.FINAL_ROS / NULLIF( AVG(f.FINAL_ROS) OVER ( PARTITION BY f.NEW_CATEGORY, mm.L1_CATEGORY ), 0 ) >= 1 AND ( ( UPPER(TRIM(mm.L1_CATEGORY)) = \'SNITCH\' AND f.STORE_COUNT > ts.TOTAL_STORE_COUNT * 0.50 ) OR ( UPPER(TRIM(mm.L1_CATEGORY)) IN (\'PLUS\', \'LUXE\') AND f.STORE_COUNT > 20 ) ) THEN \'REPEAT\' ELSE \'NO REPEAT\' END AS R2 FROM final_size_ros f LEFT JOIN lifetime_gm lg ON f.SKU_GROUP = lg.SKU_GROUP LEFT JOIN meta_mapping mm ON f.SKU_GROUP = mm.SKU_GROUP CROSS JOIN total_stores ts ORDER BY f.SKU_GROUP ; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.SRU_REPEATS_COMBINED AS WITH combined AS ( SELECT \'shopify\' AS CHANNEL, NULL AS SUB_CHANNEL, SKU_GROUP, L1_CATEGORY, CATEGORY, START_DATE, SOLD_QTY, NC_DAYS AS COUNT_OF_STORES_NC_DAYS, REVENUE, RETURN_QTY, RETURN_PCT AS RETURN_PCT, XS_ROS, S_ROS, M_ROS, L_ROS, XL_ROS, XXL_ROS, XL3_ROS, XL4_ROS, XL5_ROS, XL6_ROS, SKU_ROS, AVG_CATEGORY_L1_ROS, SKU_ROS_INDEX, SKU_STR, COGS, GM_PCT, AVG_CATEGORY_L1_RETURN_PCT, R1, R2 FROM SNITCH_DB.MAPLEMONK.SRU_REPEATS_SHOPIFY UNION ALL SELECT \'offline\' AS CHANNEL, NULL AS SUB_CHANNEL, SKU_GROUP, L1_CATEGORY, NEW_CATEGORY AS CATEGORY, NULL AS START_DATE, ( COALESCE(ALLOCATION_1_TOTAL_SALES, 0) + COALESCE(ALLOCATION_2_TOTAL_SALES, 0) + COALESCE(ALLOCATION_3_TOTAL_SALES, 0) + COALESCE(ALLOCATION_4_TOTAL_SALES, 0) ) AS SOLD_QTY, STORE_COUNT AS COUNT_OF_STORES_NC_DAYS, LIFETIME_REVENUE AS REVENUE, NULL AS RETURN_QTY, NULL AS RETURN_PCT, FINAL_XS_ROS AS XS_ROS, FINAL_S_ROS AS S_ROS, FINAL_M_ROS AS M_ROS, FINAL_L_ROS AS L_ROS, FINAL_XL_ROS AS XL_ROS, FINAL_XXL_ROS AS XXL_ROS, FINAL_3XL_ROS AS XL3_ROS, FINAL_4XL_ROS AS XL4_ROS, FINAL_5XL_ROS AS XL5_ROS, FINAL_6XL_ROS AS XL6_ROS, FINAL_ROS AS SKU_ROS, AVG_CATEGORY_FINAL_ROS AS AVG_CATEGORY_L1_ROS, ROS_INDEX AS SKU_ROS_INDEX, FINAL_STR AS SKU_STR, COGS, LIFETIME_GM_PCT AS GM_PCT, NULL AS AVG_CATEGORY_L1_RETURN_PCT, R1, R2 FROM SNITCH_DB.MAPLEMONK.SRU_REPEATS_OFFLINE UNION ALL SELECT \'mp\' AS CHANNEL, CHANNEL AS SUB_CHANNEL, SKU_GROUP, L1_CATEGORY, CATEGORY, START_DATE, QTY_SOLD AS SOLD_QTY, ( COALESCE(LIVE_DAYS_NONSOR, 0) + COALESCE(LIVE_DAYS_SOR, 0) ) AS COUNT_OF_STORES_NC_DAYS, REVENUE, RETURN_QTY, RETURNS_PCT AS RETURN_PCT, NULL AS XS_ROS, NULL AS S_ROS, NULL AS M_ROS, NULL AS L_ROS, NULL AS XL_ROS, NULL AS XXL_ROS, NULL AS XL3_ROS, NULL AS XL4_ROS, NULL AS XL5_ROS, NULL AS XL6_ROS, ROS AS SKU_ROS, AVG_ROS AS AVG_CATEGORY_L1_ROS, ROS_INDEX AS SKU_ROS_INDEX, STR_NONSOR AS SKU_STR, COGS, GP_PCT AS GM_PCT, AVG_RETURNS_PCT AS AVG_CATEGORY_L1_RETURN_PCT, R1, R2 FROM SNITCH_DB.MAPLEMONK.SRU_REPEATS_MP_SOR ), final_combined as ( SELECT c.*, bp.LIVE_DATE, bp.image_url, case when LOWER(c.R1) LIKE \'repeat%\' and lower(c.r2) like \'repeat%\' then \'repeat\' else \'no repeat\' end as final_remarks, CASE WHEN c.CHANNEL LIKE \'%offline%\' THEN COALESCE(c.SKU_ROS, 0) * 90 * 185 ELSE COALESCE(c.SKU_ROS, 0) * 90 END AS ORDER_QTY FROM combined c LEFT JOIN ( SELECT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, MAX(FINAL_LIVE_DATE) AS LIVE_DATE, max(image_url) as image_url FROM SNITCH_DB.MAPLEMONK.BASE_PRODUCT GROUP BY 1 ) bp ON UPPER(TRIM(c.SKU_GROUP)) = bp.SKU_GROUP ), current_wh_inv as ( select CASE WHEN POSITION(\'-\' IN \"Item SkuCode\") > 0 THEN LEFT(\"Item SkuCode\", LENGTH(\"Item SkuCode\") - LENGTH(REVERSE(SUBSTRING(REVERSE(\"Item SkuCode\"), 1, POSITION(\'-\', REVERSE(\"Item SkuCode\")) - 1))) - 1) ELSE \"Item SkuCode\" END AS sku_group, COALESCE(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'), \"Item SkuCode\") AS size, sum (inventory) AS INV, CASE WHEN \"Item SkuCode\" LIKE \'SN0%\' OR \"Item SkuCode\" LIKE \'4MSFR%\' OR \"Item SkuCode\" LIKE \'BP%\' THEN \'NA\' WHEN \"Item SkuCode\" LIKE \'SH0%\' THEN CASE WHEN size = \'39\' THEN \'XS\' WHEN size = \'40\' THEN \'S\' WHEN size = \'41\' THEN \'M\' WHEN size = \'42\' THEN \'L\' WHEN size = \'43\' THEN \'XL\' WHEN size = \'44\' THEN \'XXL\' WHEN size = \'45\' THEN \'3XL\' ELSE size END ELSE CASE WHEN size = \'28\' THEN \'XS\' WHEN size = \'30\' THEN \'S\' WHEN size = \'32\' THEN \'M\' WHEN size = \'34\' THEN \'L\' WHEN size = \'36\' THEN \'XL\' WHEN size = \'38\' THEN \'XXL\' WHEN size = \'40\' THEN \'3XL\' WHEN size = \'42\' THEN \'4XL\' WHEN size = \'44\' THEN \'5XL\' WHEN size = \'46\' THEN \'6XL\' WHEN size = \'48\' THEN \'7XL\' WHEN size = \'50\' THEN \'8XL\' WHEN size = \'\' THEN \'NA\' WHEN size IS NULL THEN \'NA\' ELSE size END END AS size_mapped FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE facility in (\'SAPL-WH2\',\'SAPL-WH1\',\'SAPL-NORTH-TAURU\') AND DATE = CURRENT_DATE() group by 1,2,4 ), current_wh_inv_pivot AS ( SELECT SKU_GROUP, SUM(CASE WHEN SIZE_MAPPED = \'NA\' THEN INV ELSE 0 END) AS NA_INV, SUM(CASE WHEN SIZE_MAPPED = \'XS\' THEN INV ELSE 0 END) AS XS_INV, SUM(CASE WHEN SIZE_MAPPED = \'S\' THEN INV ELSE 0 END) AS S_INV, SUM(CASE WHEN SIZE_MAPPED = \'M\' THEN INV ELSE 0 END) AS M_INV, SUM(CASE WHEN SIZE_MAPPED = \'L\' THEN INV ELSE 0 END) AS L_INV, SUM(CASE WHEN SIZE_MAPPED = \'XL\' THEN INV ELSE 0 END) AS XL_INV, SUM(CASE WHEN SIZE_MAPPED = \'XXL\' THEN INV ELSE 0 END) AS XXL_INV, SUM(CASE WHEN SIZE_MAPPED = \'3XL\' THEN INV ELSE 0 END) AS XL3_INV, SUM(CASE WHEN SIZE_MAPPED = \'4XL\' THEN INV ELSE 0 END) AS XL4_INV, SUM(CASE WHEN SIZE_MAPPED = \'5XL\' THEN INV ELSE 0 END) AS XL5_INV, SUM(CASE WHEN SIZE_MAPPED = \'6XL\' THEN INV ELSE 0 END) AS XL6_INV, SUM(INV) AS TOTAL_WH_INV FROM current_wh_inv GROUP BY SKU_GROUP ), CURRENT_INV_PIPELINE AS ( SELECT * FROM ( WITH po_base_raw AS ( SELECT CASE WHEN UPPER(TRIM(sku)) LIKE \'SN%\' OR UPPER(TRIM(sku)) LIKE \'BP%\' THEN UPPER(TRIM(sku)) WHEN UPPER(TRIM(sku)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku::STRING, \'^[^-]+-[^-]+-[^-]+\'))) WHEN UPPER(TRIM(sku)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(sku_group)) END AS sku_group, UPPER(TRIM(sku)) AS sku, UPPER(TRIM(REGEXP_SUBSTR(sku::STRING, \'[^-]+$\'))) AS raw_size, order_date::DATE AS order_date, TRIM(lot_number) AS purchase_order, transfer_branch_code, CASE WHEN transfer_branch_code = 94 THEN \'NORTH\' WHEN transfer_branch_code = 8 THEN \'SOUTH\' END AS warehouse, UPPER(TRIM(action_code)) AS action_code, COALESCE(total_qty, 0) AS total_qty, COALESCE(pending_qty, 0) AS pending_qty, from_party AS vendor_name FROM snitch_db.maplemonk.logic_purchase_order WHERE sku IS NOT NULL AND transfer_branch_code IN (8, 94) AND UPPER(TRIM(action_code)) IN (\'N\', \'M\') AND order_date::DATE > \'2026-01-26\' ), po_base as ( select sku_group, CASE WHEN raw_size IS NULL OR TRIM(raw_size) = \'\' THEN \'L\' WHEN raw_size = \'01M\' THEN \'M\' WHEN raw_size = \'01XL\' THEN \'XL\' WHEN raw_size = \'06XL\' THEN \'6XL\' WHEN raw_size IN (\'XS\', \'S\', \'M\', \'L\', \'XL\') THEN raw_size WHEN raw_size IN (\'XXL\', \'2XL\', \'XXU\') THEN \'2XL\' WHEN raw_size IN (\'XXXL\', \'3XL\') THEN \'3XL\' WHEN raw_size IN (\'4XL\', \'5XL\', \'6XL\', \'7XL\', \'8XL\') THEN raw_size WHEN raw_size = \'28\' THEN \'XS\' WHEN raw_size = \'30\' THEN \'S\' WHEN raw_size = \'32\' THEN \'M\' WHEN raw_size = \'34\' THEN \'L\' WHEN raw_size = \'36\' THEN \'XL\' WHEN raw_size = \'38\' THEN \'2XL\' WHEN raw_size = \'40\' THEN \'3XL\' WHEN raw_size = \'42\' THEN \'4XL\' WHEN raw_size = \'44\' THEN \'5XL\' WHEN raw_size = \'46\' THEN \'6XL\' WHEN raw_size = \'48\' THEN \'7XL\' WHEN raw_size = \'50\' THEN \'8XL\' WHEN raw_size = \'39\' THEN \'2XL\' WHEN raw_size = \'41\' THEN \'4XL\' WHEN raw_size = \'43\' THEN \'5XL\' WHEN raw_size = \'45\' THEN \'6XL\' WHEN raw_size = \'1\' THEN \'XS\' WHEN raw_size = \'2\' THEN \'S\' WHEN raw_size = \'3\' THEN \'M\' WHEN raw_size = \'4\' THEN \'L\' WHEN raw_size = \'5\' THEN \'XL\' WHEN raw_size = \'6\' THEN \'2XL\' ELSE raw_size END AS size, order_date, purchase_order, transfer_branch_code, warehouse, action_code, total_qty, pending_qty, vendor_name from po_base_raw ), po_dedup AS ( SELECT * FROM po_base where CONCAT(sku_group, \'|\', purchase_order) NOT IN ( SELECT DISTINCT CONCAT(upper( trim( REVERSE( SUBSTRING( REVERSE(sku), CHARINDEX(\'-\', REVERSE(sku)) + 1, LEN(sku) ) ) ) ) , \'|\', lot_number) FROM snitch_db.maplemonk.GRN_ISSUES_JOINED ) QUALIFY ROW_NUMBER() OVER ( PARTITION BY sku_group, size,purchase_order, total_qty, transfer_branch_code ORDER BY pending_qty ASC, order_date DESC ) = 1 ) , xx as (SELECT sku_group,size, SUM(CASE WHEN warehouse = \'NORTH\' THEN total_qty ELSE 0 END) AS NORTH_QTY, SUM(CASE WHEN warehouse = \'SOUTH\' THEN total_qty ELSE 0 END) AS SOUTH_QTY, SUM(total_qty) AS TOTAL_QTY, MAX(order_date) AS LATEST_ORDER_DATE, LISTAGG(DISTINCT purchase_order, \', \') WITHIN GROUP (ORDER BY purchase_order) AS purchase_orders FROM po_dedup GROUP BY sku_group,size ) select * from xx )), CURRENT_INV_PIPELINE_PIVOT AS ( SELECT SKU_GROUP, SUM(CASE WHEN SIZE = \'XS\' THEN TOTAL_QTY ELSE 0 END) AS XS_PL, SUM(CASE WHEN SIZE = \'S\' THEN TOTAL_QTY ELSE 0 END) AS S_PL, SUM(CASE WHEN SIZE = \'M\' THEN TOTAL_QTY ELSE 0 END) AS M_PL, SUM(CASE WHEN SIZE = \'L\' THEN TOTAL_QTY ELSE 0 END) AS L_PL, SUM(CASE WHEN SIZE = \'XL\' THEN TOTAL_QTY ELSE 0 END) AS XL_PL, SUM(CASE WHEN SIZE = \'XXL\' THEN TOTAL_QTY ELSE 0 END) AS XXL_PL, SUM(CASE WHEN SIZE = \'3XL\' THEN TOTAL_QTY ELSE 0 END) AS XL3_PL, SUM(CASE WHEN SIZE = \'4XL\' THEN TOTAL_QTY ELSE 0 END) AS XL4_PL, SUM(CASE WHEN SIZE = \'5XL\' THEN TOTAL_QTY ELSE 0 END) AS XL5_PL, SUM(CASE WHEN SIZE = \'6XL\' THEN TOTAL_QTY ELSE 0 END) AS XL6_PL, SUM(TOTAL_QTY) AS TOTAL_PIPELINE FROM CURRENT_INV_PIPELINE GROUP BY SKU_GROUP ), joined_inv_pipeline as ( select a.*, wh.XS_INV, wh.S_INV, wh.M_INV, wh.L_INV, wh.XL_INV, wh.XXL_INV, wh.XL3_INV, wh.XL4_INV, wh.XL5_INV, wh.XL6_INV, wh.TOTAL_WH_INV, pl.XS_PL, pl.S_PL, pl.M_PL, pl.L_PL, pl.XL_PL, pl.XXL_PL, pl.XL3_PL, pl.XL4_PL, pl.XL5_PL, pl.XL6_PL, pl.TOTAL_PIPELINE, COALESCE(pl.XS_PL, 0) + COALESCE(wh.XS_INV, 0) AS WITHPL_XS, COALESCE(pl.S_PL, 0) + COALESCE(wh.S_INV, 0) AS WITHPL_S, COALESCE(pl.M_PL, 0) + COALESCE(wh.M_INV, 0) AS WITHPL_M, COALESCE(pl.L_PL, 0) + COALESCE(wh.L_INV, 0) AS WITHPL_L, COALESCE(pl.XL_PL, 0) + COALESCE(wh.XL_INV, 0) AS WITHPL_XL, COALESCE(pl.XXL_PL, 0) + COALESCE(wh.XXL_INV, 0) AS WITHPL_XXL, COALESCE(pl.XL3_PL, 0) + COALESCE(wh.XL3_INV, 0) AS WITHPL_3XL, COALESCE(pl.XL4_PL, 0) + COALESCE(wh.XL4_INV, 0) AS WITHPL_4XL, COALESCE(pl.XL5_PL, 0) + COALESCE(wh.XL5_INV, 0) AS WITHPL_5XL, COALESCE(pl.XL6_PL, 0) + COALESCE(wh.XL6_INV, 0) AS WITHPL_6XL, COALESCE(pl.TOTAL_PIPELINE, 0) + COALESCE(wh.TOTAL_WH_INV, 0) AS WITHPL_TTL from final_combined a left join current_wh_inv_pivot wh on a.SKU_GROUP = wh.SKU_GROUP left join CURRENT_INV_PIPELINE_PIVOT pl on a.SKU_GROUP = pl.SKU_GROUP ) , doi_calculation AS ( SELECT a.*, CASE WHEN LOWER(CHANNEL) = \'offline\' AND LOWER(L1_CATEGORY) = \'plus\' THEN 80 WHEN LOWER(CHANNEL) = \'offline\' AND LOWER(L1_CATEGORY) IN (\'snitch\', \'luxe\') THEN 185 ELSE 1 END AS STORE_MULTIPLIER FROM joined_inv_pipeline a ), size_doi AS ( SELECT a.*, COALESCE(WITHPL_TTL, 0) / NULLIF( COALESCE(SKU_ROS, 0) * STORE_MULTIPLIER, 0 ) AS CURRENT_DOI, COALESCE(WITHPL_XS, 0) / NULLIF(COALESCE(XS_ROS, 0) * STORE_MULTIPLIER, 0) AS XS_DOI, COALESCE(WITHPL_S, 0) / NULLIF(COALESCE(S_ROS, 0) * STORE_MULTIPLIER, 0) AS S_DOI, COALESCE(WITHPL_M, 0) / NULLIF(COALESCE(M_ROS, 0) * STORE_MULTIPLIER, 0) AS M_DOI, COALESCE(WITHPL_L, 0) / NULLIF(COALESCE(L_ROS, 0) * STORE_MULTIPLIER, 0) AS L_DOI, COALESCE(WITHPL_XL, 0) / NULLIF(COALESCE(XL_ROS, 0) * STORE_MULTIPLIER, 0) AS XL_DOI, COALESCE(WITHPL_XXL, 0) / NULLIF(COALESCE(XXL_ROS, 0) * STORE_MULTIPLIER, 0) AS XXL_DOI, COALESCE(WITHPL_3XL, 0) / NULLIF(COALESCE(XL3_ROS, 0) * STORE_MULTIPLIER, 0) AS XL3_DOI, COALESCE(WITHPL_4XL, 0) / NULLIF(COALESCE(XL4_ROS, 0) * STORE_MULTIPLIER, 0) AS XL4_DOI, COALESCE(WITHPL_5XL, 0) / NULLIF(COALESCE(XL5_ROS, 0) * STORE_MULTIPLIER, 0) AS XL5_DOI, COALESCE(WITHPL_6XL, 0) / NULLIF(COALESCE(XL6_ROS, 0) * STORE_MULTIPLIER, 0) AS XL6_DOI FROM doi_calculation a ), purchase_calculation AS ( SELECT a.*, CASE WHEN LOWER(CHANNEL) = \'offline\' THEN 45 ELSE 90 END AS TARGET_DOI, ROUND( COALESCE(SKU_ROS, 0) * GREATEST( CASE WHEN LOWER(CHANNEL) = \'offline\' THEN 45 ELSE 90 END - COALESCE(CURRENT_DOI, 0), 0 ) / 0.80 * STORE_MULTIPLIER * (1 - LEAST(GREATEST(COALESCE(RETURN_PCT, 0) / 100, 0), 1)), -1 ) AS SKU_QTY_TO_BUY, ROUND( COALESCE(XS_ROS, 0) * GREATEST( CASE WHEN LOWER(CHANNEL) = \'offline\' THEN 45 ELSE 90 END - COALESCE(XS_DOI, 0), 0 ) / 0.80 * STORE_MULTIPLIER * (1 - LEAST(GREATEST(COALESCE(RETURN_PCT, 0) / 100, 0), 1)), -1 ) AS XS_BUY, ROUND( COALESCE(S_ROS, 0) * GREATEST( CASE WHEN LOWER(CHANNEL) = \'offline\' THEN 45 ELSE 90 END - COALESCE(S_DOI, 0), 0 ) / 0.80 * STORE_MULTIPLIER * (1 - LEAST(GREATEST(COALESCE(RETURN_PCT, 0) / 100, 0), 1)), -1 ) AS S_BUY, ROUND( COALESCE(M_ROS, 0) * GREATEST( CASE WHEN LOWER(CHANNEL) = \'offline\' THEN 45 ELSE 90 END - COALESCE(M_DOI, 0), 0 ) / 0.80 * STORE_MULTIPLIER * (1 - LEAST(GREATEST(COALESCE(RETURN_PCT, 0) / 100, 0), 1)), -1 ) AS M_BUY, ROUND( COALESCE(L_ROS, 0) * GREATEST( CASE WHEN LOWER(CHANNEL) = \'offline\' THEN 45 ELSE 90 END - COALESCE(L_DOI, 0), 0 ) / 0.80 * STORE_MULTIPLIER * (1 - LEAST(GREATEST(COALESCE(RETURN_PCT, 0) / 100, 0), 1)), -1 ) AS L_BUY, ROUND( COALESCE(XL_ROS, 0) * GREATEST( CASE WHEN LOWER(CHANNEL) = \'offline\' THEN 45 ELSE 90 END - COALESCE(XL_DOI, 0), 0 ) / 0.80 * STORE_MULTIPLIER * (1 - LEAST(GREATEST(COALESCE(RETURN_PCT, 0) / 100, 0), 1)), -1 ) AS XL_BUY, ROUND( COALESCE(XXL_ROS, 0) * GREATEST( CASE WHEN LOWER(CHANNEL) = \'offline\' THEN 45 ELSE 90 END - COALESCE(XXL_DOI, 0), 0 ) / 0.80 * STORE_MULTIPLIER * (1 - LEAST(GREATEST(COALESCE(RETURN_PCT, 0) / 100, 0), 1)), -1 ) AS XXL_BUY, ROUND( COALESCE(XL3_ROS, 0) * GREATEST( CASE WHEN LOWER(CHANNEL) = \'offline\' THEN 45 ELSE 90 END - COALESCE(XL3_DOI, 0), 0 ) / 0.80 * STORE_MULTIPLIER * (1 - LEAST(GREATEST(COALESCE(RETURN_PCT, 0) / 100, 0), 1)), -1 ) AS XL3_BUY, ROUND( COALESCE(XL4_ROS, 0) * GREATEST( CASE WHEN LOWER(CHANNEL) = \'offline\' THEN 45 ELSE 90 END - COALESCE(XL4_DOI, 0), 0 ) / 0.80 * STORE_MULTIPLIER * (1 - LEAST(GREATEST(COALESCE(RETURN_PCT, 0) / 100, 0), 1)), -1 ) AS XL4_BUY, ROUND( COALESCE(XL5_ROS, 0) * GREATEST( CASE WHEN LOWER(CHANNEL) = \'offline\' THEN 45 ELSE 90 END - COALESCE(XL5_DOI, 0), 0 ) / 0.80 * STORE_MULTIPLIER * (1 - LEAST(GREATEST(COALESCE(RETURN_PCT, 0) / 100, 0), 1)), -1 ) AS XL5_BUY, ROUND( COALESCE(XL6_ROS, 0) * GREATEST( CASE WHEN LOWER(CHANNEL) = \'offline\' THEN 45 ELSE 90 END - COALESCE(XL6_DOI, 0), 0 ) / 0.80 * STORE_MULTIPLIER * (1 - LEAST(GREATEST(COALESCE(RETURN_PCT, 0) / 100, 0), 1)), -1 ) AS XL6_BUY FROM size_doi a ) SELECT pc.* FROM purchase_calculation pc WHERE NOT EXISTS ( SELECT 1 FROM SNITCH_DB.MAPLEMONK.GS_HC_SKU_REMARKS r WHERE UPPER(TRIM(pc.SKU_GROUP)) = UPPER(TRIM(r.SKU)) AND ( ( LOWER(TRIM(pc.CHANNEL)) = \'shopify\' AND LOWER(r.REMARK) LIKE \'%shopify_repeat%\' ) OR ( LOWER(TRIM(pc.CHANNEL)) = \'offline\' AND LOWER(r.REMARK) LIKE \'%offline_repeat%\' ) OR ( LOWER(TRIM(pc.CHANNEL)) = \'mp\' AND LOWER(r.REMARK) LIKE \'%sor_repeat%\' ) ) );",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            